quests[11970] = { id = 11970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Master of Summer Lore", description = "There should be no mistake, the festival is a time for fun and laughter! However it is important that you understand the origins of this holiday. Education should be sought out and savored! .\n\nThe Festival Loremaster in the Alliance capitals can guide your way. Go now and learn!", completion = "I'll be happy to tell you what I know.", objectives = "Speak to the Festival Loremaster in any Alliance capital.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11971] = { id = 11971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spinner of Summer Tales", description = "Let there be no mistake, the festival is a time for fun and laughter! However it's important that you understand the origins of this holiday. Education should be sought out and savored! .\n\nThe Festival Talespinner in the Horde capitals can guide your way. Go now and learn.", completion = "I'd be happy to tell you what I know.", objectives = "Speak to the Festival Talespinner in any Horde capital.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11972] = { id = 11972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of Ahune", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?", progress = "Greetings, {name}.  You look worried, but you shoud rejoice.  The Frost Lord is defeated!", completion = "Yes, these shards hold the final essence of the Frost Lord in this land.  We will dispose of them and banish Ahune to the nether regions of cold.\n\nThank you, {name}.  Your name will echo in the chants of the Earthen Ring for days without end.  Please honor us by accepting this vestige, a symbol of your kinship with warmth and light.", objectives = "Bring the Ice Shards to Luma Skymother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11973] = { id = 11973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prisoner of War", description = "Malygos has taken Keristrasza to serve as his consort!\n\nWe cannot allow this to come to pass.\n\nYou must do whatever it takes to spare her such a fate, {race}.", progress = "Were you able to free her from her bonds?", completion = "So, it is done then....\n\nOur kind shall never forget the sacrifice Keristrasza has made for this cause.", objectives = "Warmage Kaitlyn wants you to free Keristrasza.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11975] = { id = 11975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now, When I Grow Up...", description = "Maybe I already asked you this, but when you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock or a Blood Knight, like I said before?  Or maybe... A rock star!!  Like Sig Nicious, the blood elf, in the Elite Tauren Chieftain!\n\nI heard that when they aren't touring, they hang out in Silvermoon City!  They just sit on a balcony in the Walk of Elders waiting for people to stop by.\n\nPlease take me there.  Please!", progress = "Elite Tauren Chieftain are the coolest!", completion = "Did you see that?  They were cheering for me!!\n\nNow I know how they feel when they are up on stage singing!  I felt the power and the energy!\n\nJust like they say in their song!\n\nMy mind is made up, I am going to be a rock star when I grow up!", objectives = "Take your orphan, Salandria, to see the Elite Tauren Chieftain in Silvermoon City's Walk of Elders. Make sure to call for her if she is not present when you arrive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11976] = { id = 11976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Shards", description = "These shards pulse with foreboding.  Do they hold the last essence of the Frost Lord?", objectives = "Bring the Ice Shards to Luma Skymother.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11977] = { id = 11977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tauren Among Taunka", description = "<Wartook points northeast.>\n\nShe is quite kind, you know. If it were not for your emissary, the surviving refugees may have given up hope. While she may not be taunka by birthright, the tribe has taken to her as a village elder for the time being.\n\nIf you are who I think you are, please go and pay Emissary Brighthoof a visit inside the refugee camp. She has been waiting for you.", completion = "What you see here is all that remains of the taunka from the Borean Tundra and the Dragonblight. They are a broken people... battered and brought to the brink of extinction by the Scourge.\n\n<Brighthoof shakes her head.>\n\nOnly the Horde can save them now. Only the Horde can mend their broken spirits. We will nurse them back to full health and they will in turn strengthen the Horde in Northrend.", objectives = "Seek out Emissary Brighthoof at the Westwind Refugee Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11978] = { id = 11978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fold", description = "Before we can officially bring these taunka into the Horde we must recover our armaments from the Anub'ar Nerubians that infest the nearby woods. The armaments were lost when a caravan from Agmar's Hammer was ambushed by the Scourge late last night.\n\nVenture out into the woods to the east of Westwind Refugee Camp and recover those armaments, {race}.", progress = "Without armor and weapons our newest members will be defenseless in their trek to Agmar's Hammer.", completion = "This is exactly what we need, {name}! Brandishing Horde arms will lift their spirits and give them the protection they need against the Scourge.\n\nAre you prepared for the ceremony of initiation?\n\n\n\nYou will be the one to admit our new allies into the Horde.", objectives = "Emissary Brighthoof at the Westwind Refugee Camp in the Dragonblight wants you to recover 10 Horde Armaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11979] = { id = 11979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Taunka and the Tauren", description = "The Scourge have seized control of the capital city of the taunka, Icemist Village! All living taunka that escaped the massacre are being held in protective custody at the Westwind Refugee Camp on the western border of Dragonblight.\n\nLord Hellscream believes that the taunka must join the Horde if they are to survive and has sent a tauren emissary to Westwind to bolster our relationship with the winter tauren. Travel to Westwind Refugee Camp and seek out Emissary Brighthoof. You will assist her.", completion = "What you see here is all that remains of the taunka from the Borean Tundra and the Dragonblight. They are a broken people... battered and brought to the brink of extinction.\n\n<Brighthoof shakes her head.>\n\nOnly the Horde can save them now. Only the Horde can mend their broken spirits. We will nurse them back to full health and they will in turn strengthen the Horde in Northrend.", objectives = "Seek out Emissary Brighthoof at the Westwind Refugee Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11980] = { id = 11980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pride of the Horde", description = "I was one of the guards chosen to escort the caravan carrying the armament shipment to this camp. The attack came fast and without warning. We fought and killed dozens of the beasts, but in the end there were simply too many. Tor'zin and I barely made it out alive...\n\nIf not for our injuries we would be out in the woods hunting down those fiends ourselves. Will you help us regain our lost pride? Search the woods east of here for Anub'ar Nerubians and kill them! For the Horde!", completion = "<Roh'kill salutes you.>\n\nYou have preserved our honor, {name}. Tor'zin and I both thank you for this selfless act!", objectives = "Blood Guard Roh'kill at the Westwind Refugee Camp in the Dragonblight wants you to slay 15 Anub'ar Ambushers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11981] = { id = 11981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Kurun!", description = "The Earthen warrior's stone surface is covered with cracks and gouges. Although it is incapable of bleeding, you can sense that the warrior is near death.\n\nA low, hoarse voice escapes from the dying warrior's mouth.\n\n\"Find... Kurun... you must find... Kurun.\"\n\nIt looks at you helplessly as you ask for any clues as to who or what Kurun might be.\n\n\"Our... leader... he stands on the... hill overlooking Thor Modan... commands us. Please... tell him... we cannot take... the city... \"", completion = "<You tell Kurun about the message given to you by the fallen Earthen.>\n\nThey fight bravely, but he is right. We will not overcome the iron dwarves of Thor Modan without help. My giants and the Earthen have long struggled against iron's evil, but our forces are not numerous enough to win the battle for Thor Modan. Will you aid us?", objectives = "Speak with Kurun on the hill overlooking Thor Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11982] = { id = 11982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raining Down Destruction", description = "Beneath us is iron's ancient bastion, Thor Modan. Thousands of years ago, the stone giants tore the land asunder, collapsing part of the city and exposing much of the rest.\n\nEven now, the iron dwarves attempt to reclaim their old capital, but we will not permit it. My giants fill the trench with boulders and debris, hoping to seal it off and kill the servants of iron as they work. Take up the boulders you see near the trench to the northeast, and help us put an end to their efforts.", progress = "What have you to report?", completion = "As quickly as we're able to fill the trench, the iron dwarves keep clearing it. Our assault from above will not take the city alone. You must aid the earthen fighting in the plaza below.", objectives = "Kurun on the hill overlooking Thor Modan wants you to disrupt the iron dwarves' work by throwing boulders into the exposed area of Thor Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11983] = { id = 11983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Oath of the Horde", description = "They are ready, {name}. These taunka will all willingly join the Horde and give all that they have to see the Scourge driven from this world.\n\n<Brighthoof hands you a scroll bearing the insignia of the Horde.>\n\nWithin this scroll you will find the blood oath of the Horde. Tradition dictates that our new taunka brothers and sisters utter the sacred words herein.\n\nTake the scroll and swear the taunka into the Horde, commander. Return the scroll to me when you have completed your duty.", progress = "They will strengthen the Horde, commander.", completion = "Thank you for doing this, Commander {name}. They had nothing left. You have given them purpose and with purpose comes hope... Hope for a new tomorrow... for a new life.", objectives = "Speak to the taunka at Westwind Refugee Camp and make 5 of them pledge their allegiance to the Horde.\n\nReturn the Blood Oath of the Horde to Emissary Brighthoof once you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11984] = { id = 11984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Filling the Cages", description = "'Ol Budd's seen better days.\n\nEver since our stay in Ghostlands he's been useless to us. We've had to find ways to make it on our own, and today that means sellin' trolls to the highest bidder.\n\nFortunately, we've recently found a use for Budd. Something about his condition allows him to mingle with the local trolls, so we taught him a little game that's turned us a tidy profit.\n\nSee for yourself. Talk to Budd, take him southwest to Drak'Zin Ruins and use this cage as soon as he tags a troll.", progress = "Have you managed to cage an ice troll?", completion = "Great work, {class}. Looks like we'll be keepin' Budd around a little longer.\n\nWe'll have your cage picked up right away. Here's your share of the bounty.\n\nOh, and welcome to the camp. Stick around and I'm sure we'll find a use for ya....", objectives = "Samir at Granite Springs wants you to use the Bounty Hunter's Cage on a drakkari troll that's been stunned by Budd.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11985] = { id = 11985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Breach", description = "If we can't overcome the defenders inside Thor Modan, the iron dwarves can hold out forever. The Earthen are bravely taking on the constructs built by the sons of iron, but they cannot break into the city.\n\nThe tunnels narrow too quickly for my fellow giants to be of use, so our options are few. Would you be willing to venture into the city and kill the dwarf commanding the resistance?", progress = "Were you able to kill the commander?", completion = "Well done, {name}. The loss of the iron dwarf commander should be enough to break the remaining defenders. The Earthen should be able to deal with the survivors.", objectives = "Kurun on the hill overlooking Thor Modan wants you to kill Iron Thane Argrum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11986] = { id = 11986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps.\n\nThe author's handwriting seems vaguely familiar, but you're unable to place it until you discover an entry signed with the name of Brann Bronzebeard.\n\nThe back half of the book, containing the most recent entries, has been torn away. Pages litter the battlefield, and it will be impossible to know what Brann discovered here until the book is whole again.", progress = "What's that you have there?", completion = "You found Brann's journal? Incredible! The league hasn't gotten a report from him in some time, and we began to fear he may have been captured or killed. What did he discover inside Thor Modan?", objectives = "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Torthen Deepdig at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11987] = { id = 11987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLDFortune Card: Silver", objectives = "You will be able to choose one of these rewards:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11988] = { id = 11988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runic Keystone", description = "Brann's journal mentions that he used a runic keystone to illuminate the important runes on the plate he discovered. Without the keystone, the plate's contents would be little better than gibberish.\n\nAt the end of Brann's last entry, he describes the iron dwarf defenders seizing the keystone from him, shattering it, and dividing it among themselves. Before we can decipher the runed plate, we must hunt down the fragments. Any of the dwarves within Thor Modan or the buildings around it may carry fragments.", progress = "Do you have enough of the fragments to reconstruct the keystone?", completion = "<Torthen works quickly to assemble the fragments you retrieved.>\n\nThis is incomplete, but it should still allow us to get most of the information from the plate.", objectives = "Bring 5 Runic Keystone Fragments to Torthen Deepdig at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11989] = { id = 11989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Truce?", description = "Watch yerself, mon.\n\nDrakuru shrunk more {race} heads than I can remember - and even if I could remember, I couldn't count that high. Lucky for you I be stuck in dis cage or I'd be addin' one more to da list.\n\nBut things bein' what they are, mebbe we be puttin' our differences aside fer a time, eh?\n\nDrakuru know things, mon. Things that will aid you in your struggle here.\n\n<Drakuru cuts the palm of his hand on one of his tusks and extends it through the cage.>\n\nSo, what you say, mon... truce?", progress = "Good choice, mon. You won't be livin' to regret it....", completion = "There!\n\nNow we be connected by blood, mon. A true bond we be havin'.\n\nYou lissen carefully to Drakuru, {race}. There be much to do.", objectives = "Drakuru at Granite Springs wants you to use the Dull Carving Knife near his cage and then speak to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11990] = { id = 11990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vial of Visions", description = "First things first, mon. There be some preparatory work that need doin'.\n\nNo tellin' how long dey gunna keep me here. Ya be needin' a powerful elixir so we can be keepin' in touch.\n\nLucky for you, I know just the thing! And the ingredients all be close by.\n\nI need a vial from the pretty little troll over there, some waterweed from the lake just north of here, and a few haze leaves found around the camp here.\n\nHurry now, mon, before dey be haulin' me away.", progress = "You got da stuff, mon?", completion = "<Drakuru takes the ingredients and deftly combines them in the vial.>\n\nThis should do it, mon. Now it be time to get to work.", objectives = "Drakuru at Granite Springs wants you to bring him a Crystal Vial, a Waterweed Frond, and 3 Haze Leaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11991] = { id = 11991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subject to Interpretation", description = "A legendary set of artifacts, lost for thousands of years, were created to make Drak'Tharon Keep impervious.\n\nMost think they be myth, but Drakuru knows better, mon!\n\nI nearly discovered where one be, but got captured while interpreting hieroglyphs. Ya gotta summon my soul back dere so I can finish readin' em!\n\nUse my elixir at da brazier on Drak'Zin Ruins, southwest of here. You'll hafta mix in da frozen mojo my bruddas be holdin'. I hate ta see my bruddas fall, but it be for the greater good.", completion = "Ahh, yes. Ya done good, mon.\n\nI be readin' the walls just fine from here....", objectives = "Drakuru wants you to get 5 Frozen Mojo from the Drakkari Trolls at the Ruins of Drak'Zin and then use the elixir at Drakuru's Brazier there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11993] = { id = 11993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runic Prophecies", description = "We've no time to lose! Now that we've reassembled the runic keystone -- well, most of it -- we can decipher the contents of those very same runic plates Brann was working on before he fled.\n\nWe have no way of knowing if he managed to read the contents of all three plates, but we'll have to assume he got enough information to determine his next destination.\n\nStand before each of the plates and use the keystone to determine the contents of each. Brann may be counting on us!", completion = "<Torthen listens as you recount the contents of the runic plates.>\n\nBy Madoran's hammer, he's discovered a whole new titan city!\n\n'The cradle of stone and iron.'\n\n'Ulduar nestled in the storm.'\n\nWhat d'you suppose that means? Could it be where we come from, after all these years?\n\nWe have to follow him! We have to find him!", objectives = "Torthen Deepdig at the Westfall Brigade Encampment wants you to decipher the three Rune Plates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11994] = { id = 11994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juno's Flag Tester" }
quests[11995] = { id = 11995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Presence is Required at Stars' Rest", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Stars' Rest with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nStars' Rest is westward past the intersection of the road leading north out of the harbor. There is an archmage there named Modera. She will be expecting you.", completion = "I've been expecting you, {class}. We have much work to do, you and I.", objectives = "Speak with the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11996] = { id = 11996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Presence is Required at Agmar's Hammer", description = "{class}, I know these tuskarr will ask you to do many favors for them, but you must get to Agmar's Hammer with all due haste!\n\nThe upheaval in the land this morning is sure to have broader repercussions than just inconveniencing the natives.\n\nThe Hammer is westward past the intersection of the road leading north out of the harbor. Archmage Aethas Sunreaver himself will be expecting you!", completion = "What took you so long? Time waits only for Aspects, {race}.\n\nWe have much work to do, you and I.", objectives = "Speak with the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11997] = { id = 11997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Frozen Flame", description = "It is time we make our move, {name}. I can conjure a portal that will take you directly inside but it will take some time before I can make another and join you.\n\nThe Lich King will no doubt sense the magic of your arrival so you will need to move fast to locate Felo'melorn and secure it.\n\nIf Lyandra has the blade with her then I fear she may not relinquish it easily. Be prepared for anything, {name}.", completion = "Felo'melorn... I can barely believe that such great power is locked within a blade as beautiful as this!\n\nWith this weapon in your hands, the Legion will surely fall!", objectives = "Obtain Felo'melorn from Lyandra Sunstrider in Icecrown Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11998] = { id = 11998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Softening the Blow", description = "Our best bet for moving our forces quickly to Icecrown Glacier lies with the network of tunnels beneath the ancient iron dwarf city of Thor Modan.\n\nBrugar Stoneshear and his Explorers' League boys aren't going to be happy, but orders are orders.\n\nThe news might go over better if you brought him a cask of that moonshine sold by that trapper, Hugh Glass, down at Redwood Trading Post, southeast of here along the tree line.\n\nMan's not right in the head, but you won't find better moonshine out here.", progress = "What's that you have there?", completion = "Let me get this straight -- a {race} I don't know brings me a cask of the finest booze in this miserable forest. Ok, then, what are you after?", objectives = "Bring Brugar Stoneshear at the Westfall Brigade Encampment a cask of Howlin' Good Moonshine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[11999] = { id = 11999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a group of Highborne elves. It was also a ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI want more information and you are going to get it for me!\n\nAfter the land was destroyed at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters there. Go rifle their corpses for clues.", progress = "You have returned.  What did you uncover?", completion = "Curious, they seek an accord with the Ethereum. The ethereals could prove a powerful ally for Malygos and his madness.\n\nThis will not do!", objectives = "Find the Moonrest Gardens Plans and return them to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12000] = { id = 12000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rifle the Bodies", description = "The Moonrest Gardens to the southwest were the final resting place of a noble group of Highborne elves. It was also a powerful ley line nexus.\n\nThe blue dragonflight used a magical device they call a surge needle to destroy that nexus, freeing the power to redirect at their will.\n\nI need more information and I hope that you will get it for me.\n\nAfter the upheaval at the ruins, the ghosts of the Highborne rose up and decimated half of the mage hunters present. Go rifle their corpses for clues.", progress = "You have returned.  What did you uncover?", completion = "Curious, they seek an accord with the Ethereum. The ethereals could prove a powerful ally for Malygos and his madness.\n\nThis will not do!", objectives = "Find the Moonrest Gardens Plans and return them to the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12001] = { id = 12001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzOLDHunting Tarot: Lesser Beasts", description = "Staring into the card, the image blurs until you see yourself standing covered in the furs from many wolves and bears.  You can only assume this is your destiny should you invoke the tarot's power.", objectives = "Collect 12 Torn Hides and then summon the Huntsman with the Hunting Tarot. The Torn Hides can only be gathered from beasts of level 5 or higher.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12002] = { id = 12002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brothers in Battle", description = "I hope Gryan knows I withdrew my men from Thor Modan when the battle began. There's no way we can excavate anything until that place settles down.\n\nYou seem like a brave sort, though, and you have Stoutmantle's trust.\n\nThor Modan is just to the northeast of us and the battle still rages between our Earthen brothers and the creations of those accursed iron dwarves. Help our brethren to even the odds and I'll start figuring out how we're going to accomplish this survey of Thor Modan.", completion = "<Brugar listens to your report.>\n\nIt sounds like things may be calming down there a bit. We'll start looking for entrances to the iron dwarves' tunnel system.", objectives = "Kill 10 Runic Battle Golems and return to Brugar Stoneshear at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12003] = { id = 12003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Tunnels", description = "The first place we'll search for entrances to the Thor Modan tunnel system will be the outlying buildings.\n\nAs I left the site with my men, it looked like the iron dwarf defenders were taking refuge inside the buildings. Be careful as you explore them.\n\nAny tunnel entrances are likely to be toward the back of the buildings. I'm not sure what Stoutmantle thinks we're going to find down there, but I doubt the iron dwarves will make the search easy.", completion = "<Brugar utters a stream of foul dwarven words.>\n\nNo entrances? None?\n\nNo, of course it couldn't be that easy. Well, I suppose there's no avoiding a foray into the city proper. My boys'll never get back to their real work.", objectives = "Brugar Stoneshear at the Westfall Brigade Encampment wants you to explore the North Building, the East Building, and the South Building of Thor Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12004] = { id = 12004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", progress = "Have you prevented the accord between the blue dragonflight and the Ethereum?", completion = "Unfortunate that Goramosh indicated the accord had already been reached.\n\nNonetheless, that's two less worms we'll have to worry about. Let us get to more important business.", objectives = "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12005] = { id = 12005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prevent the Accord", description = "We need to kill two birds with one stone here, {class}. You're the stone.\n\nOur two birds are Wind Trader Mu'fah and Goramosh. They should be somewhere in the western half of the Moonrest Gardens. Most likely they're in the larger two-story building overlooking the pit.\n\nI require proof of their demise, if you would be so kind.", progress = "Have you prevented the accord between the blue dragonflight and the Ethereum?", completion = "That's alright, {class}, just put them down on the ground there in front of Agmar's throne.\n\n\n\nUnfortunate that Goramosh indicated the accord had already been reached.\n\nNonetheless, that's two less worms we'll have to worry about. Let us get on to more important business.", objectives = "Deliver Wind Trader Mu'fah's Remains and the Scales of Goramosh to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12006] = { id = 12006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge this Atrocity!", description = "These so-called mage hunters came here and destroyed our resting place.\n\nAvenge us, or I will see to it that your base of operations is overrun with the spirits of the dead!", progress = "Somehow I sense that you haven't quite killed enough of these defilers!", completion = "Very well, you have satisfied my request if nothing more.\n\nThank you, {race}.", objectives = "Kill any combination of 15 Dragonblight Mage Hunters, Moonrest Stalkers, Surge Needle Sorcerers, and Focus Wizards. After you have done that, return to Ethenial Moonshadow at Moonrest Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12007] = { id = 12007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacrifices Must be Made", description = "I've got it, mon!\n\nTo da north, on da Ziggurat at Zeb'Halak be a stone head with ruby eyes. One o' dem be da Eye of the Prophets! Bring it to the brazier there and drink my elixir.\n\nAgain, ya be needing some mojo for my elixir to work - dis time from da warlord, Zim'bo. He be hidin' in one of da huts in Zeb'Halak.\n\nIt be a shame to kill Zim'bo, mon, but he swore da blood oath to defend Drak'Tharon and he done failed. Now at least his mojo be helpin' us to reclaim Drak'Tharon.", progress = "You get da Eye of the Prophets, mon?", completion = "Dis be it, mon!\n\nIt be even more precious than I hoped. Dis be sure to bring mah people hope in dese dark times.\n\nNo time to waste, now. Let's be seein' where da next artifact be hidin'.", objectives = "Drakuru wants you to bring the Eye of the Prophets to him at Drakuru's Brazier in Zeb'Halak.\n\nYou will need to collect Zim'bo's Mojo to use Drakuru's Elixir there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12008] = { id = 12008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agmar's Hammer", description = "Directly east of this refugee camp stands Agmar's Hammer - testament to the Hordes' power in the Dragonblight.\n\nWhile I have no doubt that our Horde brothers and sisters are already seeing the result of your efforts to bring the taunka into the Horde, I want you to deliver news of your success to Overlord Agmar in person.\n\nGo now, {name}! Race the winds! East to Agmar's Hammer!", completion = "While you have undoubtedly championed the cause of the Horde elsewhere, many more have been working towards expanding our grasp deeper into Northrend. Even now we have forces establishing bases in the frozen reaches of this desolate wasteland.\n\nWe surround the Scourge on all sides. Victory nears as our armies amass at the foot of the Wrathgate, Angrathar. Soon we will tear down the gate and breach Icecrown.\n\nBut there is much work left to be done...\n\nFirst we stop the Nerubians!", objectives = "Travel to Agmar's Hammer in the Dragonblight and speak to Overlord Agmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12009] = { id = 12009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tua'kea's Crab Traps", description = "With all of the troubles, I've lost my assistants. I was wondering if maybe you could help me?\n\nI have many crab traps under the waves of the harbor. Will you retrieve them for me? I'm too old for that sort of thing and the waters can be very dangerous.\n\nPlease, take this bladder. It will help you to breathe while you're down there.", progress = "How many crabs did you manage to retrieve?", completion = "I'm a simple trapper. The world has turned upside-down all of a sudden. It doesn't make sense.\n\nI hope that you'll be able to set it right again.", objectives = "Collect 8 of Tua'kea's Crab Traps and return them to him at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12010] = { id = 12010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Orlond", description = "When we began excavating the city, I sent Surveyor Orlond to check the stability of the tunnels in Thor Modan. I didn't see him escape when we withdrew at the beginning of the battle, and I worry he may still be trapped inside the city.\n\nIf we're going to get an army through Thor Modan, we'll need the information he was collecting. Stoutmantle and his superiors would have my hide if the tunnels collapsed on one of their brigades!", completion = "A quick examination of the body reveals that the surveyor has been dead for some time. Looking through his pack, you stumble upon Orlond's handwritten notes.", objectives = "Locate Surveyor Orlond within Thor Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12011] = { id = 12011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of Big Watery Trouble", description = "This crab trap appears to have been destroyed by something much larger than the nearby circling sharks.\n\nPerhaps Tua'kea, the fisherman at Moa'ki Harbor, should be told about this?", completion = "That's not the news I wanted to hear, {race}.\n\nNo, no... it's good that you told me, but I fear my old nemesis has returned to these waters.", objectives = "Inform Tua'kea at Moa'ki Harbor about the wrecked crab trap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12012] = { id = 12012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inform the Elder", description = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", completion = "This is grave news indeed. We must do everything in our power to stop this war from coming to pass.", objectives = "Travel to a capital city and speak to the Earthen Ring Elder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12013] = { id = 12013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "End Arcanimus", description = "There is one last thing that I would have you do, {name} the {race}. I would have you destroy Arcanimus!\n\nThe sorcerers to the west used that giant device in the sky to bore a massive pit into our resting place. When they did that, they unleashed a monstrosity!\n\nI would not care if it were only a concern for mortals, but Arcanimus feeds upon the spirits of the dead.\n\nYou will put an end to it now!", progress = "Do you think me a fool? Arcanimus is still eating the souls of my brothers and sisters, {class}!", completion = "You have my deepest gratitude, {name}.\n\nIf you haven't already, you should alert your betters to the danger that the blue dragonflight has unleashed. By blowing apart the ley line anchor underneath the gardens, they threaten to destroy us all!", objectives = "Destroy Arcanimus and then return to Ethenial Moonshadow at Moonrest Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12014] = { id = 12014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steady as a Rock?", description = "Orlond's notes indicate that he brought a piece of equipment called a portable seismograph with him, but the device is nowhere to be seen.\n\nThe survey log shows that Orlond completed all his readings in the Thor Modan tunnel, save one labeled the 'east end of the exposed tunnel.'\n\nThe last entry in the log indicates Orlond tried to take refuge in the water and was attacked by subterranean threshers. They might've taken his equipment.You'll need to recover it before you can take the last reading.", progress = "What did you find?", completion = "<Brugar looks over the report.>\n\nThis isn't good at all. Even if we could excavate the tunnels behind the blockage, there's no guarantee they wouldn't collapse again. It looks like some of these areas haven't been used in generations. We'll have to give Captain Gryan the bad news.", objectives = "Retrieve the Portable Seismograph and use it to take stability readings in Thor Modan, then return to Brugar Stoneshear at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12016] = { id = 12016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bait", description = "I'm sure of it... our ancient aquatic nemesis, Tu'u'gwar, \"He Who Plays With Food\", has returned. We must lay a trap for him, you and I.\n\nIf Tu'u'gwar has one weakness it's his stomach. There's one meat for certain that he'd never be able to pass up.\n\n\"Two Huge Pincers\", the mother of all crabs, Kili'ua, paces upon her island out in the waters to the southwest. You must pay her a visit and return with her meat.", progress = "You return with the succulent flesh of Kili'ua?", completion = "You were able to slay Kili'ua... perhaps you'll be able to do the same to Tu'u'gwar.\n\nPerhaps not.", objectives = "Obtain The Flesh of \"Two Huge Pincers\" and deliver it to Tua'kea at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12017] = { id = 12017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meat on the Hook", description = "The time has come my friend: Tu'u'gwar must be dealt with!\n\nI've prepped the meat so that the beast is sure to come once you bait the hook I have out in the water. Just follow the fishing line here down to it.\n\nWhatever you do, don't let Tu'u'gwar swallow you whole, {name}!", progress = "I thought I might have spotted some thrashing... is Tu'u'gwar dead?", completion = "We shall rejoice at your success, my young friend! There's blood in the water and it is our enemy's!\n\nYou have the eternal gratitude of this old fisherman, and most certainly of all the Kalu'ak once I spread the word!\n\nHere now, I insist, take something as a reward, please.", objectives = "Slay Tu'u'gwar and then return to Tua'kea at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12018] = { id = 12018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweet Revenge", description = "You there... you look the fighting type.  I want some sweet Revenge on the Scourge that killed my family.  Go get me 2 Stone Hunks O' Gargoyle so that I can throw them on the ground and stomp on them violently until they are mashed into itty bitty pebbly bits. \n\nYes. Go. Kill.", objectives = "Obtain 2 Stone Hunks O' Gargoyle from Carrion Gargoyles in the Eastern Carrion Fields. Return to Lord Bevis when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12019] = { id = 12019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Rites", description = "I served Arthas in death, because I had no choice.  He had control over my will and my body.  The Cult of the Damned serves Arthas in life... willingly.\n\nNow that we know the words of power to enter Naxxanar we can put an end to the cultist blight.  Go to En'kilah and look for the teleportation orb beneath the floating citadel.\n\nWork your way up and meet me at the top.  Arm yourself with what courage you can, we might not make it out of this alive.", progress = "Hail, {name}.", completion = "You did well, {name}.  I was hoping to leave my sister out of all this.  Thanks to you she is alive and well.\n\nMy obligations to my king and my army have been fulfilled.  It is clear I'm not welcome among my comrades anymore.  I will have to find my own way, fighting no wars but my own and following no orders but my heart's.\n\nPerhaps we shall meet again, {class}.  Until then, take this as a token of my gratitude.", objectives = "Go to the Temple City of En'kilah and find the teleportation orb beneath the floating Scourge citadel of Naxxanar. Use it to reach the top and help Thassarian there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12020] = { id = 12020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Boxey and explain your heroic triumph over the Dark Iron dwarves.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, {class}, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, {name}.  Enjoy the rest of Brewfest.", objectives = "Talk to Boxey Boltspinner in the Brewfest camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12021] = { id = 12021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter Home", description = "This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields.  Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.", sourceObjective = "Bring the letter home to Lady Alustra in the Eastern Carrion Fields.This letter appears to be addressed to a resident of Stormwind from one of the late Villagers in the Carrion Fields. Perhaps one of the surviving residents in the Eastern camp would be interested in forwarding it to its intended recipient.", sourceObjectiveStatus = "unverified-source-field" }
quests[12022] = { id = 12022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chug and Chuck!", description = "Hey there! You look like you can handle your brew.\n\nBut can you handle your brew mug?\n\nWe like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss!\n\nThink you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", progress = "Toss one back, then toss one forward. S.T.O.U.T. can take the abuse, it's why I built him.", completion = "Do you know what that was?  Gnomish engineering at its finest!  S.T.O.U.T. took the abuse like a champ!\n\nI think you're ready now to take on the Dark Irons if they show up again.", objectives = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12023] = { id = 12023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweeter Revenge", description = "Satisfyingly crunchy.  Now... you... {race} thing... there's an Abomination wandering the hillside to the south.  Go kill it.  Kill it good.", objectives = "Kill the Abomination on the hillside in Eastern Carrion Fields. Return to Lord Bevis once the slaughter is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12024] = { id = 12024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recording the Fallen", description = "Thank you for coming {name}.  We haven't recieved any word from Wintergarde Keep.  I'm sure they're still battling the Scourge, but I can believe they left us alone to this slaughter.  \n\nWe need to gather the names of the dead so that we can notify their families.  When the Alliance Military brought us here, we all filled out Settlement Documentation and were required to keep it on our persons.  \n\nGo sift through the corpses and bring me any Documents that you find so that I can start a list of the names.", objectives = "Search the skeletons in the Carrion Fields for Alliance Settlement Documents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12025] = { id = 12025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Scarlet Among Us", description = "It's good to see that you were not ravaged by the Scourge as well.  Perhaps you'd be willing to lend a hand.  \n\nThe Scarlet Crusade has taken up a post to the north with the obvious intent of battling the Scourge.  The thing that bothers me is that they were building before we were attacked - they must have known something.  \n\nI need to know if one of our Villagers was involved.  Search for evidence on those of us that were brought back as ghouls.  If you find anything, bring it to me.", objectives = "Search for evidence of the Scarlet Crusade on the freshly risen Carrion Ghouls in the Eastern Carrion Fields. Return to Lady Alustra with anything you find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12026] = { id = 12026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Damaged Journal", description = "This battered, mud-stained journal has seen better days. Leafing through the pages, you discover dozens of notes, diagrams, and maps in the dwarven language.\n\nThe only text you're able to decipher is the name of Brann Bronzebeard scrawled at the end of one of the entries.\n\nThe back half of the book, containing the most recent entries, has been torn away. Someone thought the notes important enough to attempt to destroy them. Perhaps gathering the missing pages from the battlefield will yield some clues.", progress = "What's that you have there?", completion = "Who is this Brann Bronzebeard? The iron dwarves found no reason to treat with him, but I have no idea why we'd be interested in his writings.", objectives = "Recover 8 Missing Journal Pages, combine them with the Incomplete Journal, and return the completed journal to Sage Paluna at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12027] = { id = 12027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mr. Floppy's Perilous Adventure", description = "Excuse me, <Mister/Ma'am>, do you know the way back to the soldiers' camp?\n\nMr. Floppy and I decided to go for a walk in the woods, and my brother Walter was gonna come with us, but then he had squire things to do.\n\nSo Mr. Floppy and I went by ourselves, but we got lost, and there were a whole bunch of hungry wolves, but we found this tower.\n\nThe wolves went away, but we're still lost.\n\nI asked Mr. Floppy, and he doesn't know the way back. Would you help us? Please?", completion = "Thank goodness you found Emmy! When she left without me, I was worried she'd get lost.\n\nI'm glad to see Mr. Floppy's back safe and sound, too.", objectives = "Help Emily and Mr. Floppy get back to the Westfall Brigade Encampment, then speak to Squire Walter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12028] = { id = 12028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Insight", description = "{race}, we have not heard from our people at Indu'le Village since the ground shook and was torn apart!\n\nHave you ever been upon a vision quest? You've bested Loguhn, so you must be capable.\n\nI will give you a special incense to sprinkle into my brazier. Breathe deep from its vapors and your spirit will be sent aloft to view what has transpired at Indu'le.\n\nAs your spirit soars, I will be able to look through your eyes.", progress = "What do you think?", completion = "Ghosts and gibbering madness? This cannot be!\n\nWe must seek further guidance.", objectives = "Speak with Toalu'u the Mystic at Moa'ki Harbor after you have attained your spiritual insight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12029] = { id = 12029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seared Scourge", description = "<Hic>... gotta burn these corpshes 'fore they shtart walkin' around again.\n\nPoppa always said, only thing worshe than havin' to kill a troll is havin' ta kill a troll twice.\n\nSay,<hic>... shpeakin' of Scourge, we can't get into tha' troll keep up north 'til we get them trolls thinned out a bit.\n\nHow 'bout ya take shome o my grog here and put them bashtards outta their misery?", completion = "Well done!\n\n<Mack laughs hysterically for a moment.>\n\nAww, come on now. That was funny...<hic>.", objectives = "Mack at Granite Springs wants you to use his grog to burn 20 Famished Scourge Trolls at Drak'Tharon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12030] = { id = 12030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elder Mana'loa", description = "My people....\n\n<The mystic is on the verge of breaking down.>\n\nWhile your spirit was flying through the village, I sensed that Elder Mana'loa took notice of you. {name}, he wishes to speak with you. The stone elders are revered by us as fonts of ancient wisdom.\n\nThe elder must want to help. Seek him in the northwest corner of the village.", completion = "I've been expecting you, {race}. I saw your spirit fly by and sensed the mystic watching behind your eyes.\n\nYour fate and that of the Kalu'ak are now tied together.", objectives = "Speak with the statue, Elder Mana'loa, at Indu'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12031] = { id = 12031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freedom for the Lingering", description = "The sacred ground of the elves to the west has been torn asunder. Now their magic is moving through the land causing ruin where it flows.\n\nThe souls of the Kalu'ak are in danger as the blue dragons forces attempt to control the magic.\n\nThe power came up through the lake, instantly slaying most in the village. Those that survived were driven insane.\n\n{name}, you must release these spirits so that they may move on. Leave the deranged living alone; they may yet regain their sanity in time.", progress = "<Elder Mana'loa looks through you, sensing that you have not yet completed his task.>", completion = "Not the most pleasant task, but necessary and merciful.\n\nAnd now there is something else that you are destined to do for the Kalu'ak.", objectives = "Put to rest any combination of 15 Indu'le Fishermen, Mystics and Warriors, then return to Elder Mana'loa at Indu'le Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12032] = { id = 12032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conversing With the Depths", description = "The watery goddess, Oacha'noa, must be consulted; only she will know what the destiny of the Kalu'ak is to be. And only The Pearl of the Depths can call her forth from the murky nether.\n\nOff the coast to the southwest rises The Briny Pinnacle. Atop it sits the altar upon which the pearl rests.\n\nCommune at the altar and Oacha'noa is certain to hear your call. Do as she says lest you incur her wrath and bring ruin upon all of the tuskarr.\n\nShould you survive, return to the mystic.", completion = "You spoke with Oacha'noa?!\n\nIf it is her will that we stand with your people then so be it. Elder Ko'nani will accept this as our destiny, for weal or woe.\n\nMy people believe that all souls are one with the magic of the world. We must oppose the blue dragon attempts to control the magic or we are all doomed!\n\nI never thought that a {race} would be the champion of the Kalu'ak, but you have proven me wrong. On behalf of my people, I give you thanks, {name}.\n\nMay the gods smile upon you and keep you safe.", objectives = "Commune with The Pearl of the Depths and do as the sea-goddess Oacha'noa instructs.\n\nShould you survive the ordeal, return to Toalu'u the Mystic at Moa'ki Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12033] = { id = 12033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Message from the West", description = "<Torvus shakes your hand, giving you a letter in the process.>\n\n<Torvus speaks under his breath.>\n\nJust play along, {name}.\n\nIt is good to see you here, soldier! Lord Hellscream has undoubtedly sent his strongest warriors to Lord Agmar!\n\n<Torvus speaks under his breath.>\n\nRead it and then destroy it in the fire pot next to me.", completion = "<Torvus nods at you.>\n\nSo we are understood? I will return to my lord and tell him that you have accepted.", objectives = "Read the Letter from Saurfang and then destroy it.\n\nSpeak to Messenger Torvus once you have completed this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12034] = { id = 12034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory Nears...", description = "There remain only two primary threats that stand in our way. One is the dread citadel of Naxxramas, far to the east, above the Alliance fortress of Wintergarde and the other is the Pit of Narjun, exit point for the undead armies of Azjol'Nerub. It is from the Pit of Narjun that the Anub'ar Nerubians assaulted and ultimately razed the taunka village of Icemist.\n\nWe will destroy the Anub'ar and close off the Pit of Narjun.\n\nReport to Senior Sergeant Juktok for your mission orders.", completion = "By land and by air, that's how we will end the Anub'ar threat.", objectives = "Speak to Senior Sergeant Juktok at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12035] = { id = 12035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Repurposed Technology", description = "Ok, I've got it!  The rewiring is a little complicated, but nothing a clever {class} like you can't handle.\n\nTake my tools and put some of the harvest collectors out of commission.  Once they're down use the tools to plug all the red wires into the blue sockets.  That'll make them go into self-defense mode.  Hurry, {name}.  Before long there won't be anything left to save.", progress = "You done yet, {name}?", completion = "Nice job!  I finally feel useful again... and that's sayin' something.", objectives = "Jeremiah Hawning at Farshire wants you to destroy 5 Harvest Collectors and then use Jeremiah's Tools to rewire them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12036] = { id = 12036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Depths of Azjol-Nerub", description = "The undead Nerubians that attacked Icemist Village came from a gigantic sinkhole known as the Pit of Narjun. If left alone, those fiends will no doubt flank our forces at the Wrathgate and end our march to victory.\n\nI need eyes on the ground, {name}. You are to head west and investigate the Pit of Narjun. We need to locate their primary exit point and seal it off! Find me that location.", completion = "That damned sinkhole must be directly connected to Azjol-Nerub. This is worse than I thought.\n\n<Juktok pauses to think for a moment.>\n\nSeek and destroy... That'll be the next course of action.", objectives = "Explore the Pit of Narjun and return with your findings to Senior Sergeant Juktok at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12037] = { id = 12037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search and Rescue", description = "Orcs... they just don't lissen <hic>. Know what I mean, {race}?\n\nKurzel's been with us fer years. You'd think she'd get a feel fer how we do things by now. Lure the fools in fer the dangerous work, then reap the rewards when it's safe. What's so hard to understand?\n\nNot her though... she goes off and takes matters into her own hands. Probably dead by now, but I'd feel horrible if we didn't follow after her, and I'm in no shape to do it myself <hic>.\n\nSo whatdya say, pal?", completion = "I knew it!\n\nEven my going missing wasn't enough to get those spineless weasels to come in here after me.\n\nWell, they sent you. I suppose that's something....\n\nHere, take this. I'd rather it go to you than to those dimwits back at the camp.", objectives = "Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12038] = { id = 12038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seared Scourge", description = "Whatcha waitin' fer, {class}? Them shcourged trolls ain't gunna kill themselves!\n\nYou know the drill. Git up ta Drak'Tharon up north... Take some o thish here grog and hurl it at 'em from a distance...<hic>.  Then jusht sit back an' watch 'em burn.", completion = "Well done!\n\n<Mack laughs hysterically for a moment.>\n\nAww, come on now. That was funny...hic.", objectives = "Mack at Granite Springs wants you to use his grog to burn 30 Famished Scourge Trolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12039] = { id = 12039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Blood of Yogg-Saron", description = "Angrathar, the Wrathgate... I watched as the metal holding the gate together pulsed and undulated as if it were alive! In 50 years I've never seen metal \"breathe.\"\n\nOnly ones who knew anything about it were the tuskarr. They called it the \"Black Blood of Yogg-Saron\" and told me to keep my distance.\n\nThere's a sinkhole outside Icemist Village to the west called the Pit of Narjun. I've heard of these sinkholes being rich with this strange ore. If you head that way, could you try and get me some samples?", progress = "What's life without risks?", completion = "It's so light... As if it weighs nothing at all! I'll need time to analyze the metal and see if I can do anything with it! Tests! I need to run tests!\n\nI'll keep in contact, {name}. If anything comes of this, you'll be the first to know.", objectives = "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to recover 10 Black Blood of Yogg-Saron Samples.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12040] = { id = 12040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Enemy in Arthas", description = "We are in the midst of a civil war. At the heart of this world the last living members of my species defend themselves against total annihilation. The Lich King seeks to rule the kingdom of Azjol-Nerub at any cost. Those that do not acquiesce are branded enemies of the Scourge and marked for death.\n\nIn Arthas we both have an enemy...\n\nJoin our cause and rid this place of the taint of Anub'ar! Let Anub'arak himself hear the anguish of their death cries!", progress = "The Azjol Empire will rise again!", completion = "There are thousands more and they spill out from every dark crevice in Northrend. Alone you stand no chance, but together... Maybe...", objectives = "Kilix the Unraveler at the Pit of Narjun in the Dragonblight has asked that you slay 6 Anub'ar Underlords.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12041] = { id = 12041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Empire", description = "You have proven that you are willing to assist the Azjol Empire in its time of need and as such the Azjol Empire will assist the Horde.\n\nTake this scroll back to your leader. It documents the strengths and weaknesses of the Nerubians attacking Icemist Village. Consider it a gesture of good faith - a willingness to help your people. Use the knowledge on those pages to crush the Anub'ar and you will have done a service for us all.\n\nFarewell, {race}.", progress = "What have you got there?", completion = "<Overlord Agmar looks over the document.>\n\nIs this what I think it is? With the information contained within these pages we will CRUSH the Anub'ar assault!\n\nYou have done well to bring this document to me, {name}. Perhaps you will be allowed to watch or even participate in the final battle at Angrathar! LOK'TAR!", objectives = "Deliver Kilix's Battle Plan to Overlord Agmar at Agmar's Hammer to the east.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12042] = { id = 12042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Ancients", description = "Secrets of da ages, be revealed to me now!\n\n<Drakuru peers through the Eye of the Prophets.>\n\nAhh, great be mah destiny, {name}. You be lucky ta know me....\n\nThere! I be seein' it, mon. The Heart of the Ancients. Dis be too easy!\n\nYou gunna find da heart lyin' near da corpse of a goblin east of here. He be up in a chamber, near a river of broken trees.\n\nHurry, mon, before someone else be findin' it!", completion = "This unfortunate goblin must have unearthed the Heart of the Ancients during his excavations in the region.\n\nIt's doubtless that he had no clue as to its nature.\n\nYou determine that it must have been overlooked in the chaos sweeping through the area.", objectives = "Drakuru wants you to go to the uppermost chamber at Blue Sky Logging Ground and find the Heart of the Ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12043] = { id = 12043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nozzlerust Defense", description = "You, {class}!  These undead south of us are being a constant nuisance to our work.  Go clear them out, will ya?", completion = "Oh!  Yeah, the undead.  Here's your coin, bugger off.", objectives = "Kill 12 Wastes Diggers and 1 Wastes Taskmaster at the digs surrounding Galakrond's Rest. Return to Narf at Nozzlerust Post when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12044] = { id = 12044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stocking Up", description = "Hello hello!  The Scourge to the south are digging up some ancient dragon thing.  I could care less why they're doing it, but they're pulling cartloads of composite ore in the process.\n\nGo lift me a bunch of that ore.  That stuff should yield a pretty penny for all the weapons the Horde are crafting.", progress = "Did you get the ore?  My carrier will be back shortly - we need to get this shipment out while the fight's still going!", completion = "Hah!  That's quite a load!  Your back feeling alright?", objectives = "Gather 8 bundles of Composite Ore from the digs surrounding Galakrond's Rest and bring them to Xink at Nozzlerust Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12045] = { id = 12045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shaved Ice", description = "I've never seen you before... are you new to the Vice?  Glad to have you.  I could always use some more hands.\n\nYou get the materials, I'll finish my machine, then we can sell it to those commander types and all go home rich.\n\nI actually have most of the primary components, so I just need some of the materials for the weapon itself.  Narf said that jagged ice shards from those elementals to the north would make perfect shrapnel for my bombs - go nab some, will ya?", progress = "Do you have the shards?  I'm almost finished with the main refrigeration unit.", completion = "Excellent!  They're even sharper than I expected them to be.  I'll pack them in the snow until the bomb is ready.\n\nLet's see... what next...", objectives = "Collect 4 Ice Shard Clusters from Ice Elementals in the north and bring them to Zivlix at Nozzlerust Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12046] = { id = 12046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soft Packaging", description = "I need some new packaging for the shrapnel bombs.  All the stuff I have is too hard and the shrapnel doesn't spread when it bursts.  \n\nWhat we need is some really thin animal hide.  Those jormungar tunnelers to the west might work... or perhaps the condors sifting through the dragon bones.  Go get me whatever you can find.", progress = "How goes the hunt?  Do you have my hides?", completion = "Good... good... these should do fine.  The shrapnel bombs are almost finished. \n\nWait... what happened to my ice shards?  Narf told me shards from those elementals should be enchanted, but they're melting just like the ones hanging from Narf's grumpy chin!", objectives = "Collect 12 Thin Animal Hides from the Jormungar Tunnelers or the Dragonbone Condors near Nozzlerust Post. Once you've located the hides, return them to Zivlix.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12047] = { id = 12047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Something That Doesn't Melt", description = "No no no! Those ice shards didn't work at all! They'll melt before they even do any damage. That's the last time I'll trust Narf's word on materials. This means we need something else entirely for the shrapnel.\n\nI know! I'm brilliant. Bone splinters.\n\nThere are some bones all around here that the jormungar have been gnawing on pretty thoroughly. Go check them out and see if you can find me some splintered bone that I can use.", progress = "Were there any splinters to be found?", completion = "Excellent!  That should be the last thing I need to test out the new bombs.  Just a moment and I'll try this out!", objectives = "Search the dragon bones east of Nozzlerust Post for 12 Splintered Bone Chunks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12048] = { id = 12048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scourge Armaments", description = "I can't make a damned thing out of this ore. It simply will not hold together! Despite my best efforts the Scourge metal will not bend!\n\nPerhaps if I had some samples of some forged Scourge armaments I might be able to reverse engineer the process by which the items are created.\n\nIcemist Village is crawling with armored Scourge Nerubians. Go there and get me some Scourge armaments! With your help I might actually succeed in creating something from this ore.\n\nYou'll find Icemist to the west.", progress = "<Borus throws his tools down.>\n\nThese are useless!", completion = "These are in excellent condition, {name}. I'll get to work right away. If anything comes of this, you will be the first to know!", objectives = "Borus Ironbender at Agmar's Hammer in the Dragonblight wants you to bring him 8 Scourge Armaments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12049] = { id = 12049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard to Swallow", description = "Those troops are sure to be needin' a hefty supply of food in their bellies.\n\nI'll let you in on a little secret that a squeamish {race} like you would never know... those jormungar worms taste just like chicken.\n\nGo provoke one of those giant hulking jormungar to the east.  You're not likely to be able to kill one straight out, so just toss this down its throat when it opens its mouth wide.  Bring me back as many of the slabs of meat as you can tote.", progress = "Did ya get it all?  You certainly stink of it.", completion = "Ha ha!  One of those meat slabs landed clear over here!  Nice work there!", objectives = "Battle a Hulking Jormungar east of Nozzlerust Post until it opens its mouth, then throw a Potent Explosive Charge into its throat. After it explodes, collect 6 slabs of Seared Jormungar Meat off of the ground and bring them back to Xink.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12050] = { id = 12050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Hack", description = "Next up, we need to haul in some lumber for all the towers the Alliance are building.  There are some thin trees to the south, but the trees the harpies are nesting in to the north look much more fit for structures.\n\nTake this.  When you get to the harpy nesting area, use the control and one of my Shredders should come to you.  Gather as much lumber as it can carry.  The harpies are sure to disagree with you chopping down their homes - just deal with them as necessary.\n\nHop to it!", progress = "Where's that carrier?  Hope the Jormungar didn't get him.  He was carrying a good sized load that time.", completion = "If a tree falls in the forest, and you can't hear it through the saw blade, does it really make a sound?", objectives = "Use Xink's Shredder Control Device to call a Shredder once you reach the Harpy Nesting Grounds in the North. Gather 50 Bundles of Lumber from the trees in the area, and then return to Xink at Nozzlerust Post.\n\nShould you lose Xink's Shredder Control Device, speak to Xink at Nozzlerust Post to obtain a new one.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12051] = { id = 12051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rustling Some Feathers", description = "Those harpies have slowed our profits long enough!  Kill them all.", objectives = "Kill 20 Harpies Northwest of Nozzlerust Post for Narf at Nozzlerust Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12052] = { id = 12052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harp on This!", description = "{class}, did you see that? That's the harpy that's been leading the attack on our shipments to the gate! I've seen her in the back of Coldwind Heights before.\n\n Those harpies have slowed our profits long enough! Kill them all.", completion = "That should make those uglies think twice.  Here... take your reward and get away with ya.", objectives = "Kill the Mistress of the Coldwind and 15 Coldwind harpies in the mountains northwest of Nozzlerust Post. Return to Narf once the task is complete.\n\nShould you be in need of Xink's Shredder Control Device, speak to Xink at Nozzlerust Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12053] = { id = 12053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Might of the Horde", description = "The taunka are now our brothers in arms. We must show our solidarity and retake Icemist Village.\n\nYou will find Icemist Village west of Agmar's Hammer, sitting at the foot of the mountains. Travel there and challenge the Anub'ar Nerubians! Plant our beloved Horde banner at Icemist Village and destroy all that dare come to tear it down!\n\nLet the Anub'ar feel the true might of the Horde! Let our battle standard be the last thing that they see before death!", progress = "It is a challenge, {name}!", completion = "We have crushed them by land! Soon we will crush them by air!", objectives = "Senior Sergeant Juktok at Agmar's Hammer in the Dragonblight wants you to use the Warsong Battle Standard at Icemist Village and defend it against attackers.\n\nReturn the Warsong Battle Standard when you are finished.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12054] = { id = 12054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deciphering the Journal", description = "Vor'takh is right -- we cannot allow this opportunity to slip through our fingers.\n\nFortunately, I think I know of a way to translate the journal of this Brann.\n\nThe shamans of the Redfang furbolgs, who congregate at the Heart's Blood Shrine south of the camp, grow an herb known as spiritsbreath. An experienced mystic can use incense made from it to seek wisdom from the spirits of the ancestors.\n\nSeek out the shaman known as Grumbald One-Eye. He should carry the herb for his devotions to Ursoc.", progress = "Have you brought sufficient quantities of the herb?", completion = "Well done, {name}. I'll prepare the incense and then we'll see what exactly this royal dwarf was doing so far from home.", objectives = "Bring a sprig of Spiritsbreath to Sage Paluna at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12055] = { id = 12055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Device", description = "Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage back at Stars' Rest to the east of the Moonrest Gardens would be able to tell what it's used for?", progress = "What do you have there?", completion = "{name}, if I'm not mistaken, you've uncovered the key to allow us to discern exactly what the mage hunter forces are up to!", objectives = "Deliver Goramosh's Strange Device to the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12056] = { id = 12056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marked for Death: High Cultist Zangus", description = "I witnessed his treachery with my own eyes! The traitor led an Anub'ar assault on this stronghold, taking out some of my best soldiers.\n\n<Gort shakes his head.>\n\nHe'd been working with the Scourge the whole time and we didn't have a clue! How many more like Zangus are there? We'll find 'em all and when we do...\n\n<Gort makes a cutting motion across his neck.>\n\nFirst on the list is Zangus. Our scouts report that he is hiding in The Pit of Narjun, west of here. Find him, kill him, bring me his head.", progress = "Is that a severed orc head in your pack or are you just happy to see me?", completion = "<Gort holds the head up and stares into its dead eyes.>\n\nI told you we'd get you...\n\nHere's your reward, {class}. That's one less headache for us to worry about.", objectives = "Kill High Cultist Zangus and return High Cultist Zangus's Head to Captain Gort at Agmar's Hammer in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12057] = { id = 12057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flesh-Bound Tome", description = "The tome is bound in flesh and appears to be bleeding. Upon examination you discover page after page filled with strange symbols that appear to be written in blood.\n\nWhatever knowledge is held within the pages of this tome could be important. Return it to Captain Gort at Agmar's Hammer, east of Icemist Village.", progress = "<Gort raises an eyebrow.>", completion = "<Gort takes the tome from you.>\n\nSavages... Bound in orc flesh... This language... Its existence has never been proven. It is the language of death... The tongue of the Scourge.", objectives = "Return the Flesh-bound Tome to Captain Gort at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12058] = { id = 12058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runic Prophecies", description = "Brann's journal also contained a guide to iron dwarf symbols. I've inscribed these on a keystone which will help you to understand the words inscribed on the rune plates.\n\nFrom the journal entries, it seems Brann may be chasing after clues to the origins of his people. Keep your eyes open for any clues as to his destination.\n\nReturn to Thor Modan, northeast of here, stand before each of the plates, and use the stone to determine the contents of each. We can't allow the Alliance to find him first.", completion = "<Sage Paluna listens as you recall the translations of the plates.>\n\nSo Brann thinks he's discovered a new titan city?\n\n'The cradle of stone and iron.'\n\n'Ulduar nestled in the storm.'\n\nI will ask the chieftain to dispatch longrunners to the Storm Peaks. My people know these lands well and have the best chance of tracking down this wayward dwarf.", objectives = "Sage Paluna at Camp Oneqwah wants you to decipher the three Rune Plates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12059] = { id = 12059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strange Device", description = "Picking up this strange device, you are certain that it is magical in nature. Unfortunately, it doesn't seem to connote any other kind of use.\n\nPerhaps the archmage back at Agmar's Hammer to the northeast of the Moonrest Gardens would be able to tell what it's used for?", progress = "What do you have there?", completion = "{name}, if I'm not mistaken, you've uncovered the key to allow us to discern exactly what the mage hunter forces are up to!", objectives = "Deliver Goramosh's Strange Device to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12060] = { id = 12060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projections and Plans", description = "This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the west.\n\nI need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.\n\nI expect that once you teleport to the top of the surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be able to use the teleporter from anywhere within the gardens.", progress = "Back so soon?", completion = "What you're describing... that's a projection of the Arcanomicon!\n\n<The archmage's show of concern is quickly masked behind an impassive countenance.>\n\nThe Arcanomicon is a map of all of the magical ley line intersections in the world. The blue dragonflight has been using it to find and destroy ley line 'anchors' to send the magical power back to the Nexus.\n\nThe question is, why is the path of destruction leading east when it should be heading west instead?", objectives = "Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens.\n\nAfterward, return to the Image of Archmage Modera at Stars' Rest with the information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12061] = { id = 12061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Projections and Plans", description = "This is a teleportation device. If I had to guess, I'd say that it leads to the surge needle platform floating above the Moonrest Gardens to the southwest.\n\n{name}, I need you to use it to investigate what's up there. It appears that the device works both ways so you shouldn't have to jump off.\n\nI expect that once you teleport up to the top of the surge needle, there will be some sort of apparatus on it to observe.\n\nYou should be able to use the teleporter from anywhere within the gardens.", completion = "What you're describing... that's a projection of the Arcanomicon!\n\n<The archmage's show of concern is quickly masked behind an impassive countenance.>\n\nThe Arcanomicon is a map of all of the magical ley line intersections in the world. The blue dragonflight has been using it to find and destroy ley line 'anchors' to send the magical power back to the Nexus.\n\nThe question is, why is the path of destruction leading east when it should be heading west instead?", objectives = "Get close to and observe the projection atop the Surge Needle floating above Moonrest Gardens.\n\nAfterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer with the information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12062] = { id = 12062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Insult Coren Direbrew", description = "Coren Direbrew is in the next room, riling up Dark Iron dwarves for another attack on Brewfest.  Defeat him!\n\nGo to Coren and pick a fight.  Tell him his beer isn't fit for pigs.\n\nWhen you do that, be ready for a fight.  The last person who insulted his brew... was fed to dire boars.", objectives = "Speak with Coren Direbrew.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12063] = { id = 12063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strength of Icemist", description = "<Greatmother Icemist bows.>\n\nIt is an honor to meet you, hero. It is because of your actions that many of us are here now, alive and ready for battle against the Scourge.\n\nYou have done so much for us that it shames me to ask you for your assistance once more. Despite my pleas, my only son, Banthok, left here to go in search of his father, High Chief Icemist. He was last seen heading west, towards Icemist Village. Please find Banthok. I do not know what I would do if I lost my son.", completion = "My father still lives! We must save him! I cannot do it alone, {race}. You must help me!", objectives = "Find Banthok Icemist at Icemist Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12064] = { id = 12064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chains of the Anub'ar", description = "They have my father bound by magical chains in the middle of Icemist Village. From what I have been able to gather, the prison is controlled by three powerful Anub'ar magi - each holding a piece of the key.\n\nScour Icemist and locate the magi. Kill them and take their key fragments. With all three pieces we might be able to free my father. Once he is free...\n\nRetribution will come swiftly.", progress = "Bring me those key fragments!", completion = "Yes, this will work.\n\n<Banthok expertly manipulates the key fragments.>\n\nHere it is, {class}. With this key, my father will be freed of the Anub'ar prison.", objectives = "Banthok Icemist at Icemist Village in the Dragonblight has asked that you bring him Anok'ra's Key Fragment, Tivax's Key Fragment and Sinok's Key Fragment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12065] = { id = 12065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Focus on the Beach", description = "The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.\n\nNo doubt the captain will have some sort of controlling device on their person. Get the controller and use it on the focus.\n\nWith any luck, we'll be able to get some more information about what they're really up to out there.", completion = "How very odd that it imprinted this information upon you magically.\n\nSo, not only do we know that they've redirected the flow of the power coming out of the Moonrest Gardens, but we now know that the power is being purposefully changed in some way. Just what are they up to with all of that magic?\n\nI don't like where this is leading, {name}, not one bit!", objectives = "Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand.\n\nThen, return to the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12066] = { id = 12066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Focus on the Beach", description = "The mage hunter forces are active on the Glittering Strand to the south of Moonrest Gardens. My guess is that you'll find a heavily guarded focus on the beach and a captain who is in charge of it.\n\nNo doubt the captain of the force down there will have some sort of controlling device on their person. Get the controller and use it on the focus.\n\nWith any skill on your part, we'll be able to get some more information about what they're really up to out there.", completion = "How very odd that it imprinted this information upon you magically.\n\nSo, not only do we know that they've redirected the flow of the power coming out of the Moonrest Gardens, but we now know that the power is being purposefully changed in some way. Just what are they up to with all of that magic?\n\nI don't like where this is leading, {name}.", objectives = "Obtain the Ley Line Focus Control Ring and use it to gain information from the Ley Line Focus on the Glittering Strand.\n\nThen, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12067] = { id = 12067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter for Home", description = "You find a letter secreted in the lining of her robes. It reads:\n\n\"Father,\n\nI'm sorry for disappearing on you. If you're reading this letter, then I'm dead.\n\nI've been forced to work for Malygos's armies under threat that our family would be killed if I didn't. I feel so ashamed.\n\nIf there's anything that you can do to fight them, don't worry about me. I have them fooled and I'm sabotaging them from the inside.\n\nI love you, Daddy!\n\nEm\"\n\nCommander Saia Azuresteel will want to see this!", progress = "A letter for me?\n\n<The commander studies your face a moment.>\n\nI suppose not... must be bad news.", completion = "Oh no... and we sent you down there to kill her, didn't we?\n\n<The commander shakes her head and sighs.>\n\nI'm sorry. I'll see to it that the letter is delivered to her father, Archmage Malin in Stormwind, right away. Don't worry, you won't be implicated... it wasn't your fault.\n\nTry to put it out of your mind. There was no way that you could have known, {name}.", objectives = "Deliver Captain Malin's Letter to Commander Saia Azuresteel at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12068] = { id = 12068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voices From the Dust", description = "<Drakuru places the Eye of the Prophets on his brow and the Heart of the Ancients on his chest.>\n\nWe be close, mon, very close!\n\nThe Drakkari Tablets be all dat remain ta be found. Nobody be knowin' how old dey be or what dey be sayin', but with the eye and the heart Drakuru can be readin' dem. Dey lie deep inside the crypt at Drakil'jin, due east of here.\n\nOnce ya got the tablets, get sacred mojo from the oracles and protectors so ya can summon me there. They'd be proud to be dyin' for such a cause.", progress = "Good to be seein' ya, {name}.\n\nYou find da tablets?", completion = "We've done it, {name}!\n\nWe have all of the components we need to perform the cleansing ritual.", objectives = "Drakuru wants you to collect the Drakkari Tablets from the Ruins of Drakil'jin and 5 Sacred Mojo from Drakkari Oracles and Protectors there. You are then to use Drakuru's Elixir at Drakuru's Brazier at the ruins to summon his image.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12069] = { id = 12069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the High Chief", description = "<Banthok hands you the prison key.>\n\nYou must hurry, {name}. Take the key and use it to unchain my father from the Anub'ar prison. Once he is freed, assist him in destroying the Anub'ar leader, Under-king Anub'et'kan. When the Under-king is defeated, take from his chitinous carapace a fragment as a trophy to present to the Horde at Agmar's Hammer. Let Agmar see the might of the High Chief!", progress = "What is it, {name}? I am extremely busy.", completion = "You are a brave {class}, {name}. You've done the Horde a great service by rescuing the High Chief.", objectives = "Free High Chief Icemist using the Anub'ar Prison Key and assist him in defeating Under-king Anub'et'kan.\n\nRecover a Fragment of Anub'et'kan's Husk and return it to Overlord Agmar at Agmar's Hammer in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12070] = { id = 12070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallying the Troops", description = "The sons of iron have used their runes to enthrall many of my brothers and are using them to break the siege on Thor Modan. I wish we did not have to fight them, but we have no choice.\n\nMy giants will not hold out long against them.\n\nI have imbued this earthen shard with a blessing that will aid our allies. Take it with you to the battle in the Boulder Hills to the north, and use it to reassure and fortify my brethren.\n\nKill any iron dwarves who would stand in your way.", progress = "Have you conveyed my blessing upon the giants?", completion = "You have given our allies the strength to fight on, and for that you have my thanks. Even so, we must begin planning a way to end this battle before we are overrun.", objectives = "Use the Shard of the Earth to rally the Grizzly Hills Giants fighting in the Boulder Hills, kill any iron dwarves who oppose you, then report to Kurun on the hill overlooking Thor Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12071] = { id = 12071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack by Air!", description = "They have seen the might of the Horde by land, now they must feel it from the air! I want you to report to Valnok Windrager at once! You will find him here, in Agmar's Hammer.\n\nValnok has already been briefed on your mission and is expecting you.", completion = "<Valnok salutes.>\n\nSo you're the hot shot, eh?", objectives = "Speak with Valnok Windrager at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12072] = { id = 12072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blightbeasts be Damned!", description = "You've no doubt seen the army of Anub'ar blightbeasts that are being constructed at Icemist Village. The Anub'ar have plans to send those monsters against our soldiers at the Wrathgate. This cannot happen!\n\nVenture west to Icemist Village with this flare gun and use it to call down one of my war riders. Climb on its back and command it to destroy the blightbeasts that are out of reach from the ground!\n\nOnce you have decimated their aerial forces, return to me for your reward!", progress = "Do note that the war riders are trained to only fight inside Icemist. Try to take them elsewhere and they will buck you off.", completion = "<Valnok salutes.>\n\nAnd now they have been crushed by air! Perhaps soon you will be called to Angrathar, hero!", objectives = "Use Valnok's Flare Gun to call down a Kor'kron War Rider at Icemist Village. Mount the Kor'kron War Rider and then use it to kill 25 Anub'ar Blightbeasts!\n\nReturn to Valnok Windrager at Agmar's Hammer should you complete this mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12073] = { id = 12073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pounding the Iron", description = "The Alliance isn't the only force opposing us in Grizzly Hills. The iron dwarves have firm control of the eastern coast, although Thor Modan, to the northeast, is besieged by stone giants.\n\nA skilled warrior uses an enemy's weakness against him and we would be fools to ignore the vulnerability of the iron dwarves at Thor Modan. Show the iron dwarves no mercy. Slay any and all who would stand in your way.\n\nThe 'sons of iron' will learn to fear the Horde.", completion = "<Scout Vor'takh smiles.>\n\nThor Modan is on the verge of collapse, then?\n\nVery well. We will soon turn our attention to Dun Argol.", objectives = "Kill any 10 Iron Dwarves defending Thor Modan and report back to Scout Vor'takh at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12074] = { id = 12074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Expedient Ally", description = "The old iron dwarf capital of Thor Modan, far to the northeast, is under siege by a mysterious band of stone giants and earthen.\n\nWhy the creations of the titans would war against each other is beyond my understanding and the Horde's interest, but there is an opportunity here to weaken a mutual enemy.\n\nTravel to Thor Modan and seek out this 'Kurun' who commands the giants and earthen. Make common cause with him and use his forces to crush the iron dwarves.", completion = "<You introduce yourself to Kurun.>\n\nSo the sons of iron are your enemies as well?\n\nMy forces have the iron dwarves pinned inside their city, but we could use help in pressing the attack. Will you aid us?", objectives = "Speak with Kurun on the hill overlooking Thor Modan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12075] = { id = 12075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slim Pickings", description = "Cold out here, isn't it, {race}?\n\nKo'char has refused to meet with me. It seems he has more pressing things on his mind - namely, the jormungar that have been attacking them from the cavern below. Maybe you can help me convince Ko'char that I'm one of the good guys.\n\nI saw a giant being eaten by some of the worms at the entrance to the cavern north of here... I'm still puzzled as to how the worms are killing them so easily. Bring me a sample from one of his wounds.", progress = "You've returned with my sample then? I'm glad the cold didn't claim you.", completion = "This is perfect.  Thank you, {class}.", objectives = "Collect a sample of Rockflesh from the Ice Giant corpse at the cavern entrance in the Crystal Vice, north of Zort's location. After this task is complete, return to Zort near the center of the canyon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12076] = { id = 12076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messy Business", description = "Even at first glance, the sample you brought me shows obvious signs of some kind of corrosive spit. It would be a natural assumption that the same substance these worms use to burrow through the ground has allowed them a formidable weapon against the Ice Giants.\n\nTake this scraper and pick a fight with some of the worms. When they spit on you, use the scraper to remove it and bring it back to me.\n\nGet me a couple samples - I'm going to have to use it as the base for an elixir.", progress = "You seem to still have some spit on your shoulder there, {race}. Be careful or it will burn right through your armor.", completion = "Still fresh.  Just a moment and I will mix this with the rest of the elixir that I have prepared.", objectives = "Collect 2 Vials of Corrosive Spit from the Jormungar by using the scraper on yourself. Bring the vials back to Zort in the Crystal Vice when your task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12077] = { id = 12077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apply This Twice A Day", description = "This elixir should protect against their spit. Offer it to Ko'char for me, will you? Tell him there's plenty more where that came from if he'll return the favor.", progress = "The runt wants us to fight for him I assume. This is my surprise face.", completion = "I will be blunt little one - I do not trust this mixture, and I will not use it. Keep it... if you find more trust in the green runt than I do, perhaps it will be of use to you.", objectives = "Offer the elixir that Zort has prepared to Ko'char the Unbreakable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12078] = { id = 12078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worm Wrangler", description = "So be it. If the giants will not come to our aid, perhaps we can make use of these worms. There are sure to be some spawn with their brood mother in the cavern below. Take this box and capture 3 of their spawn and bring them to me.\n\nWhere diplomacy fails, enslaving is a perfectly viable alternative.", progress = "You've returned! Do you have the beasts? I need to get out of here... I'm pretty sure Ko'char tried to step on me a few minutes ago.", completion = "These will do nicely. Perhaps after I grow these beasts to full size, I will bring them back and introduce them to the giants personally.\n\nBunch of useless rocks if you ask me.", objectives = "Enter the caverns in Crystal Vice and trap 3 Jormungar Spawn inside sturdy crates. Be sure to pick the crates up after the Jormungar Spawn are trapped inside!\n\nBring the captured Jormungar Spawn back to Zort in the Crystal Vice.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12079] = { id = 12079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stomping Grounds", description = "Greetings little one.  I know not what madness has brought you to the Crystal Vice, but you are welcome in my presence.  \n\nThese ice worms... these jormungar have taken a taste to eating my brothers.  I doubt you will find my kind friendly by any terms during this time of battle, but if you are here to help with the worms, then you have my ear.\n\nIf we are to take the cavern back, we must first clear the canyon of these jormungar feeders.  Join us in battle, {race}!", progress = "The battle persists, come with good news or leave me, little one.", completion = "A satisfying display of slaughter.", objectives = "Delve into the cavern at the north end of the Crystal Vice and kill 8 Ice Heart Jormungar Feeders for Ko'char the Unbreakable.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12080] = { id = 12080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Really Big Worm", description = "The jormungar have a spawnmother in the caverns below. We call her Rattlebore - a name that was gifted to her by an adventurer from the Plaguelands. I saw her only briefly as I was fighting off their initial onslaught - she is large enough to devour one of my young whole. This cavern will not be ours until she is removed from it.", completion = "So she is dead. As it should be. Your intentions do indeed prove nobler than those of the runt.\n\nThrough the north canyon you will find Crystal Song Woods.  It is a cursed and dangerous place, {race}. Should that be your next destination, proceed with caution. \n\nTake this for your efforts, little one, and leave this conflicted land with my blessing.", objectives = "Enter the Ice Heart Cavern and slay Rattlebore. If it is still in your possession, be sure to use Zort's Protective Elixir to protect you from the Jormungar's corrosive spit.\n\nReturn to Ko'char the Unbreakable in the Crystal Vice when the task is complete.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12081] = { id = 12081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gavrock", description = "Without your help, we wouldn't have been able to turn the tide of the battle for Thor Modan. This ancient city has long been a battlefield between the forces of earth and stone. I can only hope we have silenced it for the last time.\n\nThe iron dwarves can still use their magic to capture and enslave my brothers. Gavrock is searching for a way to free the runed giants. Look for him on a small cluster of islands, called the Ruins of Tethys, off the central part of the Eastwind Shore to the south.", completion = "I know Kurun is glad for your help. The defeat of Thor Modan will be a great achievement for us, but it will not free our brothers.", objectives = "Speak with Gavrock at the Ruins of Tethys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12082] = { id = 12082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dun-da-Dun-tah!", description = "Listen, kid. This is no place for you to be playin' around.\n\nI'm about to make a break for it. Stick with me and I'll get you outta here.", completion = "So, yah survived a little adventure with our good friend, did yah?\n\nThat should be reward enough in itself, but here - I'm feelin' generous.", objectives = "Escort Harrison from Drakil'jin Ruins, then speak with Harkor at Harkor's Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12083] = { id = 12083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atop the Woodlands", description = "I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor Woodlands to the southeast. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.\n\nBe careful, {name}, those woods are very dangerous.", progress = "What did you find up in the woods?", completion = "They're empowering their forces with it? That doesn't make any sense; the mage hunters aren't that powerful.\n\nThis must mean that they're only using the magic at the terminus of wherever they've redirected the ley line to.\n\nWe're going to need more information if we're to have a chance at finding and stopping them!", objectives = "Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands.\n\nThen, return to the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12084] = { id = 12084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atop the Woodlands", description = "I'm convinced that there must be more of those foci, each of them in-turn redirecting the ley line energies. We still don't know precisely what they're doing with all of that power, though.\n\nMy guess is that you'll find another one atop the Lothalor Woodlands to the south. Once again you'll need to find the person in charge and take whatever controlling device they have in their possession as I'm sure that each focus has its own.\n\nBe quick about your business, {class}. I feel that time may be running out.", completion = "They're empowering their forces with it? That doesn't make any sense at all; the mage hunters aren't that powerful!\n\nThis must mean that they're only using the magic at the terminus of wherever they've redirected the ley line to.\n\nWe're going to need more information if I'm to devise a plan to stop them!", objectives = "Obtain the Ley Line Focus Control Amulet and use it to gain information from the Ley Line Focus in the Lothalor Woodlands.\n\nThen, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12085] = { id = 12085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Letter for Home", description = "You find a letter secreted in the lining of his robes. It reads:\n\n\"Deino,\n\nTa'zinni sorry for disappearing on ya. If you're reading this letter, then I be dead.\n\nI been forced to work for Malygos's armies under threat that the family would be killed if I didn't. Ta'zinni wasn't gonna let that happen!\n\nDon't worry about me, just keep your kids safe. I have them fooled and I'm sabotaging them from the inside.\n\nI love you, sistah!\n\nTa'zinni\"\n\nOverlord Agmar is sure to want to see this!", progress = "What's this? You think you're going to mail a letter?\n\nAll mail goes through me first. There are spies and traitors amongst us!\n\n<The overlord gives you the once over and you wonder if he's going to have you killed on the spot.>\n\nVery well, be quick about it. But if I don't like what I read, I'm going to feed you to my worgs.\n\n<Agmar grins as both Gar'mak and Lak'tuk turn and look at you like you're their next meal.>", completion = "Ahahahaha... boo hoo, how touching.\n\n<The condescension in the overlord's deep-throated laughter is palpable.>\n\nWhat did I say? Traitors! Still, I knew Deino once upon a time. She at least is a troll with honor!\n\nI'll see to it that she finds out what happened to her brother. I'll even forget to tell her that you're the one that killed him.\n\n<Agmar fixes you with a calculated stare.>\n\nBut I own you now, {class}!", objectives = "Deliver Lieutenant Ta'zinni's Letter to Overlord Agmar at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12086] = { id = 12086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Son of Karkut", description = "The man you seek went far to the east, to a place near the coast called Death's Stand, beyond Unu'pe.\n\nBe careful if you go in search of him, {name}.  He bore the mark of Karkut... he who watches over the dead.", completion = "Thassarian?  Yeah he was here... what of it?  We have more pressing problems right now, my friend.", objectives = "Go east to Death's Stand, just beyond Unu'pe.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12088] = { id = 12088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thassarian, the Death Knight", description = "Well, {name}, you helped us out... so I figure it's only fair that we help you out as well.\n\nYou're looking for Thassarian?  He disappeared this morning.  We think he went off north to the Wailing Ziggurat.  If we hadn't fought side by side by him we'd even think he was a traitor.\n\nSee, he's a Death Knight... and I know they're on our side and all... but it wasn't too long ago they were servants of Arthas.\n\nBut not Thassarian, he's a good guy.  Go to the Wailing Ziggurat, see if he's doing okay.", completion = "Leryssa... is looking for me?  You must help me, {name}.  We must finish this before she gets hurt.", objectives = "Look for Thassarian inside the Wailing Ziggurat, north of Death's Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12089] = { id = 12089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Magister Keldonus", description = "By decree of Overlord Agmar:\n\nTarget: Magister Keldonus\n\nCrime: Treason\n\nStatus: Alive\n\nMagister Keldonus, once mage commander of Agmar's Hammer, is to be killed on sight in the name of the Horde.\n\nKeldonus was last seen traveling southwest towards Moonrest Gardens to join the blue dragonflight in their campaign against magic.\n\nApproach with caution as Keldonus is a powerful magus.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", completion = "He wasn't the first of those sissy spell casters to betray us, and he certainly won't be the last. Damned shame, too... He was one of our best mages. He'd summon a buffet that would make your mouth water and your heart jump for joy...\n\nBAH!", objectives = "Slay Magister Keldonus and return to Captain Gort at Agmar's Hammer in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12090] = { id = 12090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Gigantaur", description = "By decree of Overlord Agmar:\n\nTarget: Gigantaur\n\nCrime: Attacks upon the Horde; \"Bein' ugly\"\n\nStatus: Alive\n\nThe magnataur lord, Gigantaur, is wanted in relation to a number of attacks against Horde soldiers and installations in the Dragonblight.\n\nGigantaur was last seen wandering the woods and roads south by southeast of Agmar's Hammer.\n\nGigantaur should be considered armed and extremely dangerous.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", completion = "You got that ugly son-of-a-horse, eh? Well that's one less nuisance our soldiers will have to deal with out in the frozen wastes.", objectives = "Slay Gigantaur and return to Captain Gort at Agmar's Hammer in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12091] = { id = 12091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Dreadtalon", description = "By decree of Overlord Agmar:\n\nTarget: Dreadtalon\n\nCrime: Attacks upon the Horde\n\nStatus: Alive\n\nDreadtalon is wanted for numerous attacks upon Horde caravans traveling to and from Venomspite.\n\nDreadtalon makes his home on a bluff overlooking the Ruby Dragonshrine, east of Agmar's Hammer. He should be approached with extreme caution.\n\nAll bounties are paid out by Captain Gort at Agmar's Hammer.", completion = "About time someone put a stop to that filthy beast's killing spree! A job well done, {name}.", objectives = "Slay Dreadtalon and return to Captain Gort at Agmar's Hammer in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12092] = { id = 12092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthen the Ancients", description = "It's not only the {race} race that has been impacted by what the blue dragonflight forces have done. The ancients of the Lothalor Woods to the southeast have been affected as well.\n\nSome have been corrupted-- avoid them at all costs--but most can still be saved. However, the treants of the woods seem to be immune to the magic seeping through the land and the arcane wyrms that have come with it.\n\nAsk the treants for their bark and feed it to the ancients. Hopefully that will be enough to save them.", progress = "An added benefit of saving the ancients may turn out to be that they will consider assisting the Alliance with its hardships. Regardless, it is the right thing to do.\n\nNow, how many were you able to strengthen, {class}?", completion = "Thank you, {race}! We've lost so much already. You've ensured that we won't lose the most majestic of Northrend's children.\n\nI'll soon leave to speak with the ancients you saved and see if they will help us in our time of need.", objectives = "Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Sarendryana at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12093] = { id = 12093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runes of Compulsion", description = "Even as Kurun attacks Thor Modan, the iron dwarves work their magics against our brothers. Summoning our brothers from the earth, then binding them with runes, the sons of iron force them to war against the children of stone.\n\nAlong the Eastwind Shore, they use runes of compulsion to send enslaved giants to the battlefields of the north.\n\nFind the four runes of compulsion and force their overseers to appear by defeating the rune-weavers who man each rune. Without the overseers, the runes are useless.", completion = "Good. Now, we must act swiftly, before the sons of iron realize that their runes have been rendered harmless.", objectives = "Gavrock, at the Ruins of Tethys, wants you to neutralize the four Runes of Compulsion by defeating Overseer Durval, Overseer Korgan, Overseer Lochli, and Overseer Brunon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12094] = { id = 12094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Latent Power", description = "While the runes of compulsion are dormant, there is a chance we can release the runed giants.\n\nI will give you a piece of stone that has been part of me since my creation. If properly imbued, it can be used to free the bound giants.\n\nTwo ancient stone markers sit atop places of power between the Path of Iron and the forest's edge -- locations your people would call the intersections of ley lines. The other is on an island at the southern end of these ruins. Charge the shard at each stone and return.", progress = "Did you find the ancient stones?", completion = "I can detect the power you've imbued in the shard and I hope it will be enough to break the runic magic.", objectives = "Charge the Shard of Gavrock at the First Ancient Stone, the Second Ancient Stone, and the Third Ancient Stone, then return to Gavrock at the Ruins of Tethys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12095] = { id = 12095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Dragon's Fall", description = "East of here, in the heart of the Dragonblight, is a field full of nothing but dragon bones and snow. The Scourge have set up multiple camps in the central tundra and are raising frostwyrms to send against our forces at the Wrathgate. While most of these frostwyrms are easily dealt with by Rokhan and his dragon hunters, one of them is proving to be a bit problematic.\n\nGo northeast and seek out Rokhan at Dragon's Fall. Help him and his men put down Sarathstra and you'll be rewarded handsomely!", completion = "What make you tink dat you succeed where Rokhan fail?", objectives = "Speak with Rokhan at Dragon's Fall in the Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12096] = { id = 12096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strengthen the Ancients", description = "The ancients of the Lothalor Woods to the south are being corrupted by arcane wyrms... wyrms which have risen out of the ground!\n\nThose that are already corrupted are deadly and of no use to us, but most can still be saved. Luckily, the treants of the woods seem to be immune to everything happening up there.\n\nAsk the treants for their bark and when you get some, feed it to the ancients. This should strengthen them.\n\nNow leave me to my business! I have to keep an eye on these apothecaries.", completion = "You have my thanks, {class}.\n\nAs soon as I am done observing what these disgusting apothecaries are up to, I'll head to the woods and see if I can convince these ancients to side with us.\n\nOr, if nothing else, I'll convince them not to attack those that saved them!", objectives = "Use the Bark of the Walkers to strengthen 3 Lothalor Ancients and then return to Earthwarden Grife at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12097] = { id = 12097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sarathstra, Scourge of the North", description = "Me hunters be dead or frozen, {name}. You still want to do dis? Just say da word and me call for da dragon once more.\n\nIf ya kill it, take da beast's frozen heart back to Agmar's Hammer and present it to Gort. He sure to reward you good, mon.", progress = "<Gort raises an eyebrow.>\n\nBack so soon?", completion = "HA! You did it! The soldiers at the Wrathgate are indebted to you, {name}! This'll surely buy a few of them another day above ground.", objectives = "Speak with Rokhan to call down the frostwyrm, Sarathstra.\n\nKill Sarathstra and deliver Sarathstra's Frozen Heart to Captain Gort at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12098] = { id = 12098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search Indu'le Village", description = "I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, we've had absolutely no reports of there being one there.\n\nIf you would, please investigate the village for any signs of the focus or the mage hunters and their commander in the area.\n\nDon't forget to search in the lake if you have to.", completion = "You find the corpse of the mage hunter commander here.\n\nJudging by his appearance, and the condition of the forces around him, you would guess that they didn't drown. Rather, when they summoned the focus in, they didn't expect the elementals that arose from the rents in the lake bed to attack.\n\nIt would appear that the mage hunter forces were the architects of their own demise.", objectives = "Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12099] = { id = 12099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free at Last", description = "The rock shard you imbued should be powerful enough to break the runic magic binding my brothers.\n\nTake it with you and find the runed giants walking north along the Eastwind Shore. Unleash the power stored in the stone and observe the results.\n\nIf it works, the runed giants should return to their senses and stop obeying the iron dwarves. If the stone fails to work, the giants may attack in a weakened state. But, what choice do we have? If we do not try, they will remain enslaved without hope.", completion = "So it's an uncertain thing? I wish it was not a matter of chance, but at least we're on the right path. Without your help, this wouldn't have ever been possible. Should you learn any more about the machinations of the iron dwarves and their plans toward the children of stone, seek us out and we will hear you, {name}.", objectives = "Use Gavrock's Runebreaker to free 4 Runed Giants, then return to Gavrock at the Ruins of Tethys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12100] = { id = 12100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Containing the Rot", description = "With Scourge comes death and disease. We often overlook that the wildlife of a Scourge infested area is ravaged and ultimately destroyed by rot and contagion.\n\nFor most of the indigenous beasts of the Dragonblight it is too late. The festering disease that the Scourge brings has already infected the beasts and they are now rabid and rotting.\n\nYou must venture west, towards the Pit of Narjun, and cull the infected wildlife. Check their corpses for a preserved organ as we need one to devise a vaccine.", progress = "Kill the beasts to prevent the spread and bring me a rot resistant organ.", completion = "It pains me to put animals down, but it is a service that must be performed. Now we must move on to the next step: Inoculation.", objectives = "Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to kill 15 Infected Wildlife and recover a Rot Resistant Organ.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12101] = { id = 12101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Doctor...", description = "Our Forsaken allies have sent their apothecary core here to assist us in destroying the Scourge at the Wrathgate. One among them, Doctor Sintar Malefious, is well versed in the Scourge rot and methods of containing the spread. I had previously worked out a deal with him in regards to devising a vaccine for wildlife. He's since been waiting on the organ.\n\nDeliver this rot resistant organ to Dr. Malefious and let him know it's from me. He'll direct you on your next task.", progress = "What now?", completion = "The oafish man-cow actually acquired a rot resistant organ? Curses... I was certain that task would keep his malformed mind occupied well into the next millennium.\n\nWell give it here, boy. I have much to do without your feeble needs getting in the way.", objectives = "Deliver the Rot Resistant Organ to Doctor Sintar Malefious at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12102] = { id = 12102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Search of the Ruby Lilac", description = "How fortuitous it is that the Ruby Dragonshrine lays just to the east. It is there that you will find a flower called the ruby lilac. This lifegiving plant is all that I need to concoct a vaccine for the untainted beasts of this region.\n\nTravel east and search the Ruby Dragonshrine for the lilac.\n\nJust one thing: The dragonshrine, like all the dragonshrines in this blasted wasteland, is beset by the Scourge. Watch your step. We wouldn't want you to be devoured by an emberwyrm.\n\n<Sintar laughs.>", progress = "Do you have the ruby lilac?", completion = "That wasn't so difficult, now was it?\n\nNow give me a moment to prepare the vaccine.", objectives = "Doctor Sintar Malefious at Agmar's Hammer in the Dragonblight wants you to collect 1 Ruby Lilac.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12103] = { id = 12103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before the Storm", description = "{name}! I have been looking all over this strange city for you!\n\nGrand Master Hight has requested all senior monks to return to the Peak of Serenity as soon as possible. That means you too, of course.\n\nI'll bet a week's worth of brew that this has something to do with the assault on the Broken Shore I've heard tales about!", completion = "Welcome back to the land of the living, {name}. We nearly lost you in that explosion! Lucky for us that the Wandering Isle happened to be traveling nearby.\n\nThe people here have graciously allowed us to reside at the temple. It's not like the Peak of Serenity, but this will make a fine new home.", objectives = "Assist Grand Master Hight at the Peak of Serenity.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12104] = { id = 12104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Soar", description = "<Doctor Malefious hands you a vial full of murky liquid.>\n\nHere you are then, {race}. Take this back to the cow and let him know that all debts have been paid. We are officially \"square.\"\n\nNow leave me before I set Jennings upon you.", progress = "Have you got the vaccine?", completion = "<Soar holds the vial up to the sky and examines its contents.>\n\nOnly one thing left to do now.", objectives = "Deliver Sintar's Vaccine to Soar Hawkfury at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12105] = { id = 12105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Descent into Darkness", description = "The journal was written by a denizen of Silverbrook named Mikhail.  It details the arrival of a shadow-worshipping group called the \"wolfcult.\"\n\nThe villagers were reluctant to embrace the cult at first, but sympathizers sprung up gradually among town residents.\n\nUnsettled by this, Mikhail sent his daughter Sasha away from Silverbrook while he attempted to reason with the other villagers.\n\nMikhail's last entry mentions a meeting of local town leaders to discuss unspecified events in Hollowstone Mine.", progress = "What's that you've got there?", completion = "I imagined there would be more to this than just an isolated town of hostiles.\n\nWe have men near Hollowstone Mine, perhaps it would be in our interest to do a little research.", objectives = "Bring Mikhail's Journal to Lieutenant Dumont in Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12106] = { id = 12106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Search Indu'le Village", description = "I'm certain that you'll find the next ley line focus somewhere in the remains of Indu'le Village to the southeast. The problem is, I've had absolutely no reports of there being one there.\n\nI need you to go investigate the village for any signs of the focus or the mage hunters and their commander in the area.\n\nSearch in the lake if you have to!", completion = "You find the corpse of the mage hunter commander here.\n\nJudging by his appearance, and the condition of the forces around him, you would guess that they didn't drown. Rather, when they summoned the focus in, they didn't expect the elementals that arose from the rents in the lake bed to attack.\n\nIt would appear that the mage hunter forces were the architects of their own demise.", objectives = "Search for the commander of the mage hunter forces at Indu'le Village and Lake Indu'le.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12107] = { id = 12107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Line", description = "Within his robes you find two things of interest.\n\nOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.\n\nThe water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.", completion = "WHAT?!\n\n<The image before you distorts for a moment as the archmage attempts to regain her composure.>\n\nOf course, we should have guessed that this was what they were up to all along. Quickly, there's no time to waste.\n\nWyrmrest must be warned!", objectives = "Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge.\n\nAfterward, return to the Image of Archmage Modera at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12109] = { id = 12109, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to Gryan Stoutmantle... Again", description = "The Westfall boys were sent east to look for a path into the northern territories.  Their secondary objective is to secure strategic resource points, so I'm sure they wouldn't mind investigating a mine.\n\nLook for the Westfall Brigade encampment far to the northeast and seek out Gryan Stoutmantle.  You might remember him if you ever spent any time in Westfall.  Make sure to tell him I sent you.\n\nHe'll be more than happy to let you claim a functioning mine for the king.", completion = "Dumont sent you?  Very well.  Let's see what you can do for us.", objectives = "Speak to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12110] = { id = 12110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Line", description = "Within his robes you find two things of interest.\n\nOne is a talisman, which is clearly a focus controlling device. The other is a set of orders from someone named Sidragos, which were ultimately intended for the leader back at the Moonrest Gardens.\n\nThe fragile water-soaked parchment informs Goramosh that he is to move all mage hunter forces east to the Azure Dragonshrine.\n\nPerhaps you should get what information you can from the focus and head east to observe the dragonshrine from its western ledge.", completion = "WHAT?!\n\n<The image before you distorts for a moment as the archmage attempts to regain his composure.>\n\nOf course, we should have guessed that this was what they were up to all along. Quickly, there's no time to waste.\n\nWyrmrest must be warned!", objectives = "Use the Ley Line Focus Control Talisman to gain information from the Ley Line Focus under Lake Indu'le. Then, head east to the Azure Dragonshrine near south central Dragonblight and observe what is occurring there from the western ledge\n\nAfterward, return to the Image of Archmage Aethas Sunreaver at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12111] = { id = 12111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where the Wild Things Roam", description = "Inside this pack are several vials containing the vaccine that Sintar created. I now want you to search the nearby woods for Snowfall elk and arctic grizzlies. When you locate the animals, find a safe distance and throw a vial in their general direction. The vial will shatter and release a fine gas that will act as the inoculating agent. The beasts merely have to step inside the gas and they will be vaccinated - ultimately saved.\n\nInoculate as many of the beasts as you can and return to me.", completion = "You have done an honorable thing, {name}. Please, choose a reward.", objectives = "Soar Hawkfury at Agmar's Hammer in the Dragonblight wants you to use the Pack of Vaccine to vaccinate 5 Snowfall Elk and 5 Arctic Grizzlies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12112] = { id = 12112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stiff Negotiations", description = "Well it seems you were of a bit of use after all. It's not been my experience to meet many a {race} that are.\n\nWe don't have any more use for you here. Head into the Vice and see if my brother Zort could use a hand. He went to see if he could con the giants into laying down their lives so that we don't have to. He certainly wasn't known for having the brains in the family.", completion = "I can think of some uses for you, go ahead and stay for a bit.", objectives = "Locate Zort in the center of the Crystal Vice, northeast of Nozzlerust Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12113] = { id = 12113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nice to Meat You", description = "G'day to ya, {class}! Have yerself a seat by me fire, eh?\n\nI'd offer to share a nice hot meal, only I ain't got one. I'm stuck here waitin' on an associate, or I'd be out tryin' to remedy that situation meself.\n\nSay, you seem to have nuthin' but time on yer hands and there be plenty o' meat in these parts. What say ya lend a hand and round up some grub?", progress = "Me belly be rumblin, {race}. You manage to round up some food?", completion = "Outstanding!\n\nNuthin' better with a pint than a hot morsel of meat.", objectives = "Harkor at Harkor's Camp wants you to collect 10 pieces of Fibrous Worg Meat from Duskhowl Prowlers and 10 Shovelhorn Steaks from Longhoof Grazers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12114] = { id = 12114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therapy", description = "Trolls... me hates 'em all! <Harkor spits.>\n\nI once got meself captured by a band o' tha beasts... came this close ta gettin' me head shrunk!\n\nMe friends tell me to just move on and put it all behind me, but that just ain't sittin' right.\n\nWanna know what would make me feel better, {race}? Seein' a pile of their corpses so high it blots out the sun! I've got good gold to spend if ya can make that happen.", completion = "Thankyeh, {class}.\n\nWhen time allows I'll git up and have meself a look around.", objectives = "Harkor at Harkor's Camp wants you to kill 10 Drakkari Protectors and 10 Drakkari Oracles outside Drakil'jin Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12115] = { id = 12115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koltira and the Language of Death", description = "There is one who recently joined our cause that might be able to decipher this tome. An unbound death knight known as Koltira Deathweaver has temporarily taken residence here at Agmar's Hammer. As he was once a death knight of Arthas and member of the Scourge, he might be able to translate the language of the dead.\n\nTake the flesh-bound tome to Koltira and ask him to translate the pages.", progress = "What is it, {race}?", completion = "There are only two things in life that interest me, peon, and neither of them involve translating a Scourge tome for you.\n\nHowever... perhaps we could work something out that would benefit the both of us.\n\n<Koltira unsheathes his weapon.>\n\nThis is my runeblade, Byfrost. Byfrost thirsts for the blood of the Lich King and his minions, but first I must etch upon it runes of power: symbols of frost, blood, and unholy. Bring me suitable sources of power and I will translate your tome.", objectives = "Take the Flesh-Bound Tome to Koltira Deathweaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12116] = { id = 12116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Takes Guts....", description = "Greetings, {class}. It is kind of you to stop and listen to Kraz's tale.\n\nFor many years Kraz has strained to hear the spirits and do their bidding.\n\nRecently,  many voices have been crying to Kraz from these ruins. They seek for a peace they cannot find on their own.\n\nIf you would help the spirits of those who have come before, enter this crypt and collect something that once belonged to those tormented souls.", progress = "What have you found in the crypt for Kraz, {class}?", completion = "Entrails? An interesting choice, {race}.\n\nKraz shall see what is to be learned from them. Thank you for braving the depths of that place.", objectives = "Kraz at Harkor's Camp wants you to enter Drakil'jin Ruins and collect 5 Drakkari Canopic Jars.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12117] = { id = 12117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Moa'ki Harbor", description = "{race}, word just arrived from Moa'ki Harbor. Something very bad happened over there this morning!\n\nYou've been very helpful to us here. Would you consider using the boat from Unu'pe to travel to the great Dragonblight?\n\nBy the sound of things, Elder Ko'nani could certainly use your assistance.", completion = "What's that you say, {race}? Hotawa sent you?\n\nGood, good... there's much to do. We can use all of the help that we can get!", objectives = "Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12118] = { id = 12118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Travel to Moa'ki Harbor", description = "{race}, word just came in off the boat from Moa'ki Harbor. Something very bad happened over there this morning!\n\nYou've been very helpful to us here. Would you consider using the boat to travel to the great Dragonblight?\n\nBy the sound of things, Elder Ko'nani could certainly use your assistance.", completion = "What's that you say, {race}? Anuniaq sent you?\n\nGood, good... there's much to do. We can use all of the help that we can get!", objectives = "Travel to Moa'ki Harbor in the Dragonblight and speak with Elder Ko'nani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12119] = { id = 12119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining an Audience", description = "{name}, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.\n\nThank you for all that you have done on our behalf. Safe journeys!", progress = "Yes, what can I do for you, {race}?", completion = "A letter of introduction to meet with the queen? Let me see that.\n\nWhatever your business is, I hope that it's important.  The skies are full of attacking blues today!", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12120] = { id = 12120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drak'aguul's Mallet", description = "Corruption....\n\nEven before you delivered these jars, Kraz could sense it. This corruption fills the ancient Drakkari spirits with great angst and prevents them from entering the rest they seek.\n\nKraz will not lie, {class}. Cleansing this place will require great sacrifice, but we shall speak of that at another time.\n\nThere is one among the living here who holds the key to its cleansing. Seek out Drak'aguul and return to Kraz with the mallet he carries.", progress = "You find the mallet, {name}?", completion = "You have done well thus far, {name}, but now comes the true test.", objectives = "Kraz at Harkor's Camp wants you to slay Drak'aguul outside Drakil'jin Ruins and return with the Drakil'jin Mallet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12121] = { id = 12121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See You on the Other Side", description = "These Drakkari have met you with nothing but savage hostility. You owe them nothing. Few indeed would carry out the task that Kraz asks of you today.\n\nTo cleanse this place and send the spirits to their eternal rest, you must join them in death.\n\nThere is one inside the crypt who awaits you - on the other side. He holds the knowledge we seek, {name}.\n\nUse the mallet on the gongs. The spirit of he who corrupts this place will surely deliver you to the spirit world.\n\nKraz awaits your return.", completion = "Your coming has been foretold, friend. It was good of you to come.", objectives = "Kraz at Harkor's Camp wants you to use the Drakil'jin Mallet on the gongs outside Drakil'jin Ruins. Once you have been slain, you are to enter the ruins and speak with the spirit of Gan'jo while you are dead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12122] = { id = 12122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaining an Audience", description = "{name}, you must travel as swiftly as you can to Wyrmrest Temple and present this letter to the steward, Tariolstrasz.\n\nThe temple sits in the center of the Dragonblight. Follow the road east until it ends, and then cross The Dragon Wastes to get to it.\n\nI'm sure that when the steward reads your introduction, he'll see to it that you gain an audience with Queen Alexstrasza. We can only hope that we're not too late.\n\nThank you for all that you have done on our behalf. Safe journeys!", progress = "Yes, what can I do for you, {race}?", completion = "A letter of introduction to meet with the queen? Let me see that.\n\nWhatever your business is, I hope that it's important.  The skies are full of attacking blues today!", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Tariolstrasz at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12123] = { id = 12123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing the Queen", description = "<The dragon steward pulls your letter of introduction out of his sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.", progress = "It is good to finally meet you in person, {name}. I have known you since before you were born.", completion = "You are very courageous to bring us this information. I was beginning to wonder why the blue dragonflight had so boldly initiated an attack upon the temple itself. Now we know that they are using enormous amounts of the very magic they view as such a threat to Azeroth.\n\n<The queen shakes her head in seeming resignation.>\n\nHypocritical, but so be it. If Malygos will not come to his senses, we have no choice but to take action in response to their assault.", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12124] = { id = 12124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Informing the Queen", description = "<The dragon steward pulls your letter of introduction out of his sleeve.>\n\nYes... yes, I think that you are ready to see the queen now.\n\nWhen you are ready, speak to me again and I will see to it that one of these drakes delivers you safely to the top of the temple. You will need to present your letter in person to Queen Alexstrasza.", progress = "It is good to finally meet you in person, {name}. I have known you since before you were born.", completion = "You are very courageous to bring us this information. I was beginning to wonder why the blue dragonflight had so boldly initiated an attack upon the temple itself. Now we know that they are using enormous amounts of the very magic they view as such a threat to Azeroth.\n\n<The queen shakes her head in seeming resignation.>\n\nHypocritical, but so be it. If Malygos will not come to his senses, we have no choice but to take action in response to their assault.", objectives = "Deliver your Letter of Introduction to Wyrmrest Temple to Alexstrasza the Life-Binder at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12125] = { id = 12125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of Blood", description = "The blood of innocents was once used to sate the thirst of the blade. Alas, such options are no longer available to me.\n\n<Koltira pauses to think.>\n\nWe must improvise. South of here, upon the high bluffs, is the tuskarr village of Indu'le. Having been recently overrun by the Blue Dragonflight's chaotic magic, the resident tuskarr of Indu'le have gone mad.\n\nTake this blood gem and use it on a deranged villager. If I cannot take the blood of innocents, I shall have the blood of the meek!", progress = "Bring the blood of the meek to me.", completion = "A simple task for a simpleton. You have performed within my expectations.", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Blood Gem on a Deranged Indu'le Villager and return to him with a Filled Blood Gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12126] = { id = 12126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of the Unholy", description = "The power of the unholy is coveted among my kind. It makes up the very fiber of our existence, granting death to those that dare make a mockery of it! Thankfully there is a font from which I may draw from in my time of need.\n\nTake this unholy gem and make your way to the Ruby Dragonshrine, east of here. It is there that you will find Duke Vallenhal, death knight of Arthas. Weaken his resolve in battle and unleash the power of the gem upon him. It will finish him off and steal his unholy energy!", progress = "Fill the gem with the power of the unholy!", completion = "<Koltira's eyes widen.>\n\nImpressive. You bested a deathknight of Arthas... Clearly you were not alone... but still...", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Unholy Gem on Duke Vallenhal and return to him with a Filled Unholy Gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12127] = { id = 12127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Service of Frost", description = "The biting cold protects the death knight while repelling his enemies. He that commands the power of frost can incite chaos and destruction!\n\nTake this frost gem and travel far across the open tundra of the Dragonblight until you come upon the Mirror of Dawn, east of Wyrmrest Temple. It is there that you are to battle the legions of ice revenants that dwell upon the lakes surface and take from them the essence of frost. Utilize the power of the gem when they are weak, {name}!", progress = "We are all in service of frost here in Northrend.", completion = "I can already feel the cold coursing through me, {name}.", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to use the Frost Gem on Ice Revenants and return to him with a Filled Frost Gem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12128] = { id = 12128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Check Up on Raegar", description = "With all the excitement about the army trying to move through Thor Modan, I'd almost forgotten about Raegar's crew down at Prospector's Point.\n\nI sent Raegar and his assistants, along with a mountaineer friend, down to establish a small post near Dun Argol, at the southern end of the Eastwind Shore.\n\nThey were to investigate the iron dwarf presence in the southern hills, but I haven't received any reports yet. Could you check up on them if you're going down that way?", completion = "Hmm... you don't look like a research assistant, which is just as well. The iron dwarves look to be preparing for war, and my research team hasn't returned. We could use some help around here.", objectives = "Speak with Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12129] = { id = 12129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Plan", description = "The iron dwarves are making no secret of the fact that they're preparing for war. With their giants, golems, and lightning elementals, they'd have a technological advantage against the Westfall Brigade. If they don't find passage north in time, the irons could take them by surprise.\n\nWe've got to tie them up here, and I've got just the way to do it. Dun Argol is full of rune-smiths churning out war golems. They carry plans for specific pieces, so you'll need to find and assemble all the parts.", progress = "Were you able to get those plans from the rune-smiths?", completion = "You got all of them? Brilliant! I can't wait to see the looks on their faces when the golem's done.", objectives = "Bring the completed War Golem Blueprint to Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12130] = { id = 12130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Why Fabricate When You Can Appropriate?", description = "We've got the blueprints, but we can't do anything with them without parts! We don't have access to a foundry, much less materials, but there's a whole load of parts up in Dun Argol.\n\nYour job?\n\nGive them a new home.\n\nThey're likely to be scattered around any of the buildings where the iron rune-smiths are working, and I wouldn't blame the irons for being cranky when you try to filch their handiwork. The more parts you can bring, the better we can make this golem.", progress = "I see you made it out in one piece. Do you have the parts?", completion = "<Raegar wipes his forehead with the back of his hand.>\n\nOh, no. This is going to be harder than I thought. These things don't have serial numbers or anything, do they?\n\nNever a gnome around when you need one...", objectives = "Bring 8 War Golem Parts to Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12131] = { id = 12131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have the Power", description = "We're almost there, but the war golem won't run without power cells. From the information I was able to collect in Dun Argol before we were discovered, both Rune-Smith Durar and Rune-Smith Kathorn each create one power cell.\n\nWe'll need one power cell from each of the rune-smiths before our golem will work.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", progress = "Well, did you get those power cells?", completion = "<Raegar takes the batteries from you.>\n\nExcellent! We should be all ready to go.", objectives = "Bring Durar's Power Cell and Kathorn's Power Cell to Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12132] = { id = 12132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power to Destroy", description = "While you have done much for me, one task remains.\n\nBeside the world you know exists another world. It is from that world, the world of shadows, that my tormentors assault me. While I am powerless to face my own demons, you could end their reign of terror. You have the strength, I have seen it with my own eyes.\n\nEnter the world of shadows and face the demons that torment me!\n\nDo this and I will translate the tome, as promised.", completion = "The power I hold comes at a great cost, {name}. Many knights, light and dark alike, lost their lives in the final battle at Light's Hope. The prospect of the future looks grim, but at least now I know what I face. The Lich King will never release his grasp and for that alone he must die!", objectives = "Koltira Deathweaver at Agmar's Hammer in the Dragonblight wants you to enter the world of shadows and defeat 6 Shadowy Tormentors.\n\nSpeak to Koltira Deathweaver should you need to re-enter the world of shadows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12133] = { id = 12133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", progress = "Yes, {name}?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  It must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, {name}.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself.", objectives = "Give the Scorched Holy Symbol to the Costumed Orphan Matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12134] = { id = 12134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasha's Hunt", description = "This thing... this curse... that's affecting Silverbrook and Solstice Village... it makes beasts out of people.\n\nMy father tried to warn them, but they all listened to the wolfcult instead.\n\nThey're too far gone now, it's time to put them down... for their own sake.", progress = "Have you taken care of the hunters in the village yet, {name}?", completion = "Killing these monsters won't bring my father back... but that's not the point now, is it?", objectives = "Sasha wants you to kill 12 Solstice Hunters in Solstice Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12135] = { id = 12135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Let the Fires Come!\"", description = "You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe!\n\nPlease, {name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.", objectives = "The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them. When they are out, speak again to the Costumed Orphan Matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12136] = { id = 12136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Translated Tome", description = "Here it is, {name}. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent.\n\nTheir network of spies and operatives is impressive, to say the least.\n\nFarewell, friend. May the book serve you and your people well.", progress = "It's about time! Where have you been?", completion = "<Gort takes the tome from you and begins reading.>\n\nWHAT! This can't be right. I've known some of these orcs for years!\n\nLeave me, {name}. I have much work to do and many traitors to execute.\n\nTake one of these items for your trouble. You've done a great service for the Horde this day.", objectives = "Deliver the Translated Flesh-bound Tome to Captain Gort at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12137] = { id = 12137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chill Out, Mon", description = "It be as the prophecies said, mon. A {race} {class} be comin' to set our spirits to rest. We been waitin' for a long time now!\n\nThe Drakkari have become a lost people, fierce and savage.\n\nBut here we suffer by no fault of our own, mon. This place need cleansin' and only the living can do it.\n\nSpeak to me when ya be ready to rejoin your body. Then take the snow from the chest near me here and put my bruddas to sleep.\n\nTake their remnants to your spirit guide. He be knowin' what to do next.", progress = "Have you completed your task in the crypt, {class}?", completion = "You have done well.\n\nPlease, sit and listen. There are many things we must discuss.", objectives = "Gan'jo wants you to collect the Snow of Eternal Slumber from his chest in the Drakil'jin Ruins.\n\nYou are to use the Snow on the Ancient Drakkari Spirits there and take their Drakkari Spirit Particles back to Kraz at Harkor's Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12138] = { id = 12138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Or Maybe We Don't", description = "You'd think the guys making the power cells would've thought to power them up, but no, they've got to make it difficult for us.\n\nFine, we'll charge those cells the hard way. There's enough power in them to run the golem for a short time, but don't expect it to be any good in combat.\n\nYou see the lightning sentries that the irons have posted around the perimeter of Dun Argol? Bring the golem with you, take it close to them, and use the golem to absorb the power as the sentries die.", completion = "Finally, it's ready. I only hope it holds together long enough to get the job done. If we don't take out the thane leading Dun Argol, Captain Gryan'll be in for a nasty surprise.", objectives = "Charge your War Golem with the energy from 10 Lightning Sentries and return to Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12139] = { id = 12139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Let the Fires Come!\"", description = "The Headless Horseman will attack the village at any moment!  Fires will be everywhere!\n\n{name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today.", objectives = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12140] = { id = 12140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hail Roanauk!", description = "Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a leader born of their own blood. The one you saved from Icemist, Roanauk, will be this leader.\n\n<Overlord Agmar hands you a parchment.>\n\nI give to you something familiar - the blood oath of the Horde.\n\nTake the oath to Roanauk Icemist and initiate him into the Horde as leader of the taunka.\n\nLet us not keep him waiting.\n\n<Agmar nods.>", progress = "Do not waste time, {name}. Angrathar awaits!", completion = "With the aid of such a powerful shaman, we are sure to be victorious at the Wrathgate!", objectives = "Seek out Roanauk Icemist at Agmar's Hammer and initiate him as a member and leader of the Horde forces.\n\nReturn to Overlord Agmar with the Blood Oath of the Horde when you complete this task.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12141] = { id = 12141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Diplomatic Mission", description = "I see that you are very eager to help, {name}.  You didn't come all the way to Northrend to stay holed up in a city!  I've just the task for you... something that'll take you far away from here.\n\nWe've long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn't offer at the time.\n\nNow that you're around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.", completion = "You've come to my aid?  I thank you, {name}.", objectives = "Speak to Karuk at Riplash Strand, southwest of Valiance Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12142] = { id = 12142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Control", description = "Ugh! One of those little snobold runts trashed our camp while we were busy with that last dragon. They've been plaguing us whenever we turn our backs... I've had enough!\n\nTo the south you'll find the snobolds hiding under the skirts of some of the local magnataur. Go slaughter them.\n\nIf the magnataur interfere on behalf of their slaves, kill them as well.", completion = "Good riddance.", objectives = "Duane at the 7th Legion Front wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12143] = { id = 12143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canyon Chase", description = "I can't believe this! Another band of those vermin just tried to take off with more of our supplies. They're scurrying off towards that north canyon, get after them and deal with whoever they're going to!", completion = "Chilltusk, eh?  I've heard his name before.  That's some good work, {class}.  Hopefully we can turn our attention back to the dragon menace now.", objectives = "Duane wants you to chase the snobolds down the canyon northeast of 7th Legion Front and deal with their leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12144] = { id = 12144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Control", description = "Oi, mon! One of dose little snobold runts trashed our camp during da last dragon attack. Dey've been houndin us wheneva we turn our backs and I've had enough. \n\nTo da east you'll find da snobolds hiding under da skirts of some of da local magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill dem as well.", progress = "Did ya finish off dose pests?", completion = "Good riddance, mon.", objectives = "Kontokanis at Dragon's Fall wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12145] = { id = 12145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canyon Chase", description = "I can't believe dis! Another band of dose vermin just tried ta take off with more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with whoever dey're going to!", completion = "Icefist, eh?  I've heard his name before.  Dat's some good work, mon.  Hopefully we Darkspear can turn our attention back to dat dragon menace now.", objectives = "Kontokanis wants you to chase the snobolds down the canyon south of Dragon's Fall and deal with their leader.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12146] = { id = 12146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur.\n\nTake the horn south down the Path of the Titans to Wyrmrest and seek out someone who might be interested in these threatening implications.", progress = "Yes, {race}?", completion = "It is indeed strange for any magnataur to carry an item such as this... and very concerning. I am glad that you have shown this to me.", objectives = "Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12147] = { id = 12147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur. \n\nTake the horn east across the Dragon Wastes to Wyrmrest and seek out someone who might be interested in these threatening implications.", progress = "Yes, {race}?", completion = "It is indeed strange for any magnataur to carry an item such as this... and very concerning. I am glad that you have shown this to me.", objectives = "Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12148] = { id = 12148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Such a strange seal to see among magnataur... it suggests an unusual amount of organization.\n\nMagnataur rarely put aside their aggressive natures to cooperate with each other.  I suspect they have their eyes set on raiding a large settlement.\n\nI very much doubt that this horn is unique, I need you to prove me wrong. In the canyon northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring me back any evidence you find that might confirm my concerns.", progress = "Did you find anything?", completion = "So it is true. They could not have chosen better timing for such an attack... between the Scourge and the blue flight, it is unlikely that anyone else has noticed yet.", objectives = "Find and kill Bonesunder in or near the canyon northwest of the Azure Dragonshrine. Bring any evidence you find back to Aurastrasza at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12149] = { id = 12149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mighty Magnataur", description = "Magnataur are hideously violent creatures... this is the main reason we rarely see them come together in any real numbers without killing each other. A powerful leader has stepped up somewhere among them and we need to hunt him down if we are to stop this threat. \n\nI will start asking around. I need you to disrupt them as much as possible in the meantime.\n\nEast of here there are 3 torches erected. Near them, there are 3 dominant Magnataur - put them down to buy us some time to hunt down this leader.", completion = "Excellent work. No one could tell me who this leader might be, but I was able to uncover the name of someone who will have our answer.", objectives = "Hunt down and kill Bloodfeast, Iceshatter, and Drakegore east of Wyrmrest Temple.\n\nBloodfeast resides in the southeastern corner of the Dragon Wastes, just north of the Emerald Dragonshrine. Iceshatter patrols the northern edge of the Mirror of Dawn. Drakegore wanders at the bottom of the cliffs west of the Bronze Dragonshrine.\n\nReturn to Aurastrasza at Wyrmrest Temple once the magnataur have been slain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12150] = { id = 12150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclusive Runemaster", description = "Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally solitary, but has been known to associate with the more powerful and influential magnataur in Dragonblight for quite some time. He will know who this new leader is. \n\nIt is unlikely we will gain any aid with the increasing concerns with the Scourge and the blue flight, so I need you to procure the information from Dregmar by any means necessary.\n\nI was told he can be found amongst the cliffs overlooking the Mirror of the Dawn.", completion = "Grom'thar the Thunderbringer. Good. Let's end any threat these magnataur might pose here and now.", objectives = "Locate Dregmar Runebrand near his cave on the path to the cliffs overlooking the Mirror of the Dawn. Challenge him and uncover the name of the magnataur leader by any means necessary. Return to Aurastrasza at Wyrmrest Temple once the information is obtained.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12151] = { id = 12151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanton Warlord", description = "There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this.\n\nFollow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge.\n\nWhen Grom'thar the Thunderbringer arrives, kill him and bring me his head.", progress = "Did you end this threat for good?", completion = "You are formidable indeed.\n\nWith Grom'thar the Thunderbringer gone, we can leave the remaining Magnataur to fight among themselves and turn our attentions back towards more prominent threats.\n\nImpressive work, {class}.", objectives = "Travel to the ring of torches south of the Azure Dragonshrine and blow the Emblazoned Battle Horn. Defeat Grom'thar the Thunderbringer and bring his head back to Aurastrasza at Wyrmrest Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12152] = { id = 12152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'arrak's End", description = "It is good to see you back among the living. Many who travel the path of the dead do not return to speak of it.\n\nWhile you were away, a vision appeared to Kraz revealing what remains to be done.\n\nA sacred offering lies somewhere inside the crypt. Take this spirit dust fashioned from the remnants you collected and use it on the offering.\n\nThe infused offering will bring an end to the corrupted warlord and will release the many tormented souls.\n\nMay the spirits guide your actions, {name}.", completion = "It is done.\n\nYour selflessness has brought eternal peace to many souls, ending eons of misery.\n\nMay this act lighten your own soul and lessen your burdens, for I see that there are yet many perils you must face.\n\nFarewell, {name}.", objectives = "Kraz at Harkor's Camp wants you to collect the Sacred Drakkari Offering from the Drakil'jin Ruins and use the Drakkari Spirit Dust on it. You must use the Infused Drakkari Offering at the gongs outside of Drakil'jin Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12153] = { id = 12153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Thane and His Anvil", description = "Now that you've charged up your war golem, we're going to put all that energy to good use. Activate the golem inside Dun Argol to take control of it.\n\nOur  information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard protects him from all harm.\n\nThat bodyguard is the construct he travels with, called The Anvil. Disable the construct, and his protection will disappear.\n\nThe thane stays in the building at the top of Dun Argol and supervises production from the bottom level.", completion = "It worked?\n\n<Raegar clears his throat.>\n\nI mean... of course it worked! This is incredible!\n\nYears from now, Explorers' League initiates will hear the story of how Raegar Breakbrow, {name}, and some hunk o' junk golem defeated the thane of Dun Argol!", objectives = "Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12154] = { id = 12154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackout", description = "The large hall at the top of Dun Argol houses the power source for the entire area. If you can destroy the power core, it will cripple Dun Argol for some time.\n\nNo power means no golems, no sentries, and no more lightning armaments.\n\nWhen we were sent up here, they told us these explosives were for excavation, but thanks to Iron Thane Furyhammer, the research has been scrapped. We may as well get some use out of them, though. They're the only thing we have on hand capable of destroying the power core.", completion = "<Raegar nods approvingly.>\n\nI can't stand to see explosives go to waste and it'll set our enemies back for sure.", objectives = "Use Raegar's Explosives to destroy the Runic Power Core at Dun Argol, then report to Raegar Breakbrow at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12155] = { id = 12155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", progress = "Yes, {name}?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  It must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, {name}.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself.", objectives = "Give the Scorched Holy Symbol to the Masked Orphan Matron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12156] = { id = 12156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRECAED", description = "I was meant to set off for Silverbrook, northwest of here, about an hour ago.  My military escort appears to be running late.\n\nI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.\n\nWe're negotiating a deal with the locals and timeliness is essential.  What do you say?  If you come with me, you'll be well compensated for your troubles.", sourceObjective = "Escort the Alliance Envoy to the town of Silverbrook. Report to Lieutenant Dumont at the Amberpine Lodge when you've completed this task.I was meant to set off for Silverbrook, northwest of here, about an hour ago. My military escort appears to be running late.\n\nI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.\n\nWe're negotiating a deal with the locals and timeliness is essential. What do you say?  If you come with me, you'll be well compensated for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[12157] = { id = 12157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Courier", description = "We're lucky we made it this far, {name}.  We were ambushed by Scourge as soon as we landed.\n\nOne of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top.\n\nI've sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name.", completion = "As I crossed the bridge into Dragonblight a small group of Anub'ar ambushed me! I was surrounded! Those monsters knew I was coming. I barely made it out of there with my flesh intact. This list I hold must be taken to Wintergarde Keep, but I am too badly injured to make the journey.", objectives = "Speak to Courier Lanson at Stars' Rest in Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12158] = { id = 12158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollowstone Mine", description = "I've been meaning to send some of our lads to check out Hollowstone Mine.  Haven't had a chance to yet -- we've had our hands full between the Horde on the west and the iron dwarves to the east.\n\nIf Dumont sent you, though, the least I can do is point you in the right direction.\n\nYou'll find the mine entrance to the northwest, not far from here.  See if you think operations there can be salvaged.  We sure could use the additional resources until our mine in Farshire is operational again.", completion = "You've come to help me, haven't you!", objectives = "Look for clues inside Hollowstone Mine northwest of the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12159] = { id = 12159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls at Unrest", description = "<Petrov looks deeply disturbed, breathing heavily and shifting his gaze nervously around the mine.>\n\nMy comrades... we must put their souls to rest!  I kill them and kill them but.. they just come back!\n\nI've had an idea for a while but I just don't have the heart to do it myself.\n\nMaybe you can do this for me?  Take this lantern and use its oil to burn their remains so they never get up again.\n\nI'll answer your questions later.  Help my friends first!", completion = "Rest in peace friends!  Do not worry -- I will tell everyone that we never gave up!", objectives = "Petrov at Hollowstone Mine wants you to use the Miner's Lantern to burn the corpses of 8 Hollowstone Miners.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12160] = { id = 12160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Name from the Past", description = "It worked!  It worked!  My comrades can finally enjoy their well-earned rest...\n\nI'll stay here and finish the job.  We Hollowstone miners always finish the job -- we never give up!\n\nThat's why Arugal made an example of us.  We wouldn't fall in line, you see?  We wouldn't join his wolfcult!", completion = "Curse our luck.  We find the one functioning mine this side of the hills and it's full of Scourge.\n\nNo offense, friend.  But that survivor you found sounds like he's been a little traumatized due to losing his friends.  Arugal's been dead for years... I even saw his grave once.", objectives = "Return to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12161] = { id = 12161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna the Blind", description = "Hey there.  I overheard what you were saying to the captain and I just want you to know...  things aren't that simple in Northrend.\n\nJust because someone's dead it doesn't mean they're out of the picture.\n\nSouthwest of here, near Vordrassil Pass, lives a blind woman who goes by the name Ruuna the Blind.  They say she speaks to the dead and has visions of the past and future.\n\nI haven't heard your whole story but it sounds like she'd be right up your alley.", completion = "You seek knowledge beyond your reach so you've come to me.  I must warn you, stranger, the answers I provide might not be to your liking.", objectives = "Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12162] = { id = 12162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solstice Village" }
quests[12163] = { id = 12163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Evil Below" }
quests[12164] = { id = 12164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hour of the Worg", description = "It is time, then, {name}.  Arugal must be defeated.\n\nGet a couple of people you can trust and head for Bloodmoon Isle.  It's just off the coast, east of here.\n\nWe'll hit them fast.  Take out Arugal's lieutenants -- I'll catch up with you when it's time to take out the monster himself.", completion = "We got him good, {name}.  But not good enough.\n\nOne thing's for sure... we won't be seeing him around these parts any longer.", objectives = "Sasha at the White Pine Trading Post wants you to go to  Bloodmoon Isle and slay Selas, Varlam, Goremaw and the Shade of Arugal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12165] = { id = 12165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Intriguing Plan", description = "Prospector Rokar has decided to help us. He's concocted a plan to use the iron dwarves' strength against them.\n\nI must admit, our new 'friend' is more insightful than I'd given him credit for. He's correct in that our numbers are too few for a direct attack.\n\nTravel to Dun Argol, in the snowy regions to the southeast, and capture all the parts of their war golem blueprints from the iron rune-smiths there. Bring the assembled blueprint to Rokar and we'll see if his plan has any merit.", progress = "Do... do you have those blueprints I asked for?", completion = "So Tormak's going to go ahead with the plan? I suppose he wouldn't have sent you if he didn't.\n\nOh, bother... Now how am I going to figure out how to put this together under all this pressure?", objectives = "Bring the completed War Golem Blueprints to Prospector Rokar at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12166] = { id = 12166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Liquid Fire of Elune", description = "{race} will you assist me?\n\nThe Scourge have moved into Icemist to the north. Wherever they go, they spread their taint, and the creatures of the land suffer.\n\nTake this vial, which is filled with the liquid fire of Elune from the moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that you find.", completion = "We have done what we can for the creatures of the land. Now we must take direct action against those that have caused this!", objectives = "Warden Jodi Moonsong at Stars' Rest has asked you to use the Liquid Fire of Elune to cleanse the corpses of 6 Blighted Elk and 6 Rabid Grizzlies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12167] = { id = 12167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Cultists", description = "The Anub'ar cultists are indirectly responsible for the plaguing of the beasts, and we must put an end to it!\n\nThe fumes that emit from the cultists' suits seep into everything they come near, poisoning and corrupting their surroundings.\n\nYou must go north to Icemist Village and slay them. Bring back any of their suits that survive your assault and I will see to it that they are properly disposed of.", progress = "The cultists are a blight upon creation!", completion = "Well done.\n\nI will dispose of these filthy garments by cleansing them in the moonwell and destroying them through the power of the goddess!", objectives = "Collect 5 Functional Cultist Suits for Warden Jodi Moonsong at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12168] = { id = 12168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Favor of Zangus", description = "An inscription on the back of the favor reads,\n\n\"To my favorite pupil,\n\nIf you continue to show promise, I will teach you wonders beyond your imaginings.\n\nIf you do not, I will have you destroyed!\n\nAs ever,\n\nHigh Cultist Zangus\"\n\nNo doubt the warden at Stars' Rest will want to see this.", progress = "I sense something foul is near.\n\nIt is upon your person! What is it, {name}?", completion = "So, the leader of the cultists has revealed himself. We have a name.\n\nVanity and pride will be his downfall!", objectives = "Deliver the Favor of Zangus to Warden Jodi Moonsong at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12169] = { id = 12169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Cultist", description = "I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north.\n\nYou know your target, {name}. If there's to be an end to the suffering of the land, the high cultist must die!", completion = "With the high cultist destroyed, the rest of his forces can be mopped up and the land and its creatures will recover.\n\nThank you, {name}. May the goddess illuminate your path.", objectives = "Warden Jodi Moonsong at Stars' Rest has asked you to slay High Cultist Zangus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12170] = { id = 12170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Brawl", description = "The Venture Company abandoned operations shortly after we showed up.  Clearly they were afraid of what we were going to do to their greedy little hides.\n\nWith them gone, their logging camps are up for grabs.  Our war machine is a hungry beast... without renewing our supplies we won't make it to Icecrown.\n\nUnfortunately the Alliance seems to have the same idea and we must make sure we're the ones that prevail.  Head into the logging camp and help us fight the Alliance scum.", completion = "Well done, {name}.  Our control over the logging camp might not be complete yet, but thanks to you we're one step closer to smashing these Alliance worms.", objectives = "Raider Captain Kronn wants you to slay 10 Alliance units or players at the Blackriver Logging Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12171] = { id = 12171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Palena Silvercloud here at Stars' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!", progress = "Hello, {race}.", completion = "<Palena reads the note.>\n\nYou will take my fastest hippogryph, {race}! This information must be delivered to High Commander Wyrmbane at once!", objectives = "Show the Alliance Missive to Palena Silvercloud at Stars' Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12172] = { id = 12172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attunement to Dalaran", description = "Welcome, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I will help you.\n\nBut before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process.\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.", completion = "Very well. If you are ready, then so am I.", objectives = "The Image of Archmage Modera at Stars' Rest has asked you to become Attuned to the Ley Lines of Northrend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12173] = { id = 12173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attunement to Dalaran", description = "Hello, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test.\n\nBefore I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process!\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.", completion = "Very well. If you think you are ready, then let's not waste anymore of my time.", objectives = "The Image of Archmage Aethas Sunreaver at Agmar's Hammer has asked you to become Attuned to the Ley Lines of Northrend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12174] = { id = 12174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Commander Halford Wyrmbane", description = "<Palena hands the missive back to you.>\n\nSnowstorm will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!", progress = "What have you got there, soldier?", completion = "<The High Commander reads the missive and then crumples it up.>\n\nDo you know where the people on this list are now? Take a look outside, near the front gate. They're the ones hanging from the arches.\n\nGhoul bait...", objectives = "Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12175] = { id = 12175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gray Worg Hides", description = "Let me tell you something, mon.  When you get put in charge of outfittin' the armies of the Horde, you go through a lot of hides!\n\nConqueror Krenna, the she-wolf runnin' this place, she gave me a tight deadline.  If I don't outfit her whole regiment by week's end she's gonna have me wrestling bears in the pit.\n\nHelp me out and I'll pay you top price.  I'll be needin' hides from graymist hunters.\n\nYou'll find them all around in pockets to the north, hunting stag.  Remember, mon.  Top price!", progress = "You get dose hides, mon?", completion = "You're a life saver, brother.  If you're interested in more work, there's more where that came from.", objectives = "Hidetrader Jun'ik in Conquest Hold wants you to get 3 Gray Worg Hides from Graymist Hunters in the woods to the north.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12176] = { id = 12176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Minor Substitution", description = "Krenna, she be wantin' worg hides for all the outfits.  There's not gonna be enough worg hides for her army, though.  Not now, not ever.\n\nThose worgs -- they be skinny, mon!  Here's what we're gonna do... if you can keep a secret that is.\n\nEast of Voldrune there be grizzly bears as fat as an ogre.  Those large hides -- those we can use!\n\nHurry, <brother/sister>.  Krenna's not known for her patience.", progress = "You get those hides, mon?", completion = "I'm in your debt, mon.  Take this as payment.", objectives = "Hidetrader Jun'ik wants you to bring him 6 Grizzly Hides.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12177] = { id = 12177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jun'ik's Coverup", description = "Ah, we have a small problem.  Grizzly hides... they be brown, mon!\n\nThink... think!\n\nI got it, mon!  Is like this: gray is black an' white all mixed up.  You get me some coal an' some flour, I'll grind it all up and dust the hides with it.  No one will know the better!\n\nBlacksmiths sell coal for smeltin' an' you can get flour from the provisioner.", progress = "You get the stuff, mon?", completion = "Hope for the best, mon.", objectives = "Bring 1 piece of Coal and 5 Simple Flour to Hidetrader Jun'ik at Conquest Hold in Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12178] = { id = 12178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Krenna", description = "This is it, mon.  Let's take these hides to Krenna and see if they pass the test.\n\nLet's hope for both our sakes Krenna doesn't notice anything.", progress = "Do you have any idea who you're talking to?", completion = "Just who do you take me for?  These hides smell of flour!\n\nThis is a complete insult to the Horde!", objectives = "Take the Bundle of Hides to Krenna in Conquest Hold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12180] = { id = 12180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Prospectors", description = "Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar's team never expected Dun Argol to be this heavily populated.\n\nThey're being held captive while the iron dwarves prepare for war. We haven't the men to charge in after them, and Raegar's too busy fantasizing about defeating the irons to be of much help.\n\nIt falls to you, {name}. Any of the irons or their servants could be carrying the keys to the cages holding our men.", progress = "Did you locate the missing prospectors?", completion = "<Mountaineer Kilian listens as you relate what the captive prospectors told you.>\n\nThey mentioned Loken and a war against stone giants? You're certain?\n\nSo Raegar's instincts were right. We have to find a way to get in there and learn more about their plans.", objectives = "Free Prospector Gann, Prospector Torgan, and Prospector Varana, then return to Mountaineer Kilian at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12181] = { id = 12181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give it a Name", description = "My, my, how long has it been? How long have we been working on this damned plague? Finally, after an eternity of failure, we are blessed with perfection. This... It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight will tear down the very fabric of life!\n\n<Harris hands you a vial.>\n\nNow, find the bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite.", progress = "Highly lethal poisonous gas delivery to Venomspite? Step right up!", completion = "Uh, yea, you can go ahead and hold on to that vial, friend. I trust you.", objectives = "Show the Blight Specimen to Tobias Sarkhoff at New Agamand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12182] = { id = 12182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Venomspite!", description = "I got a special bat all lined up for you, buddy. Fastest and smoothest ride I've got. He'll take you right to Venomspite - in style.\n\nJust hand that vial over to Chief Plaguebringer Middleton once you land.", progress = "You are the delivery boy?", completion = "Oh joyous day! And look, just beyond the mountain to the northeast creeps a whole field of Scourge for us to obliterate!", objectives = "Deliver the Blight Specimen to Chief Plaguebringer Middleton at Venomspite in eastern Dragonblight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12183] = { id = 12183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking the Part", description = "If, as Prospector Varana said, only certain irons are permitted to communicate with this Loken, it'll probably be the overseers who have the privilege.\n\nWe have to get you in there to see what all this is about, but it won't be easy. The first step will be to get a proper uniform for you.\n\nThen, we'll worry about doing your makeup.\n\nFind one of the overseers at Dun Argol, kill him, and bring back his uniform. If you get blood on it, you'll have only yourself to blame.", progress = "Did you get the uniform?", completion = "<Kilian takes the uniform from you.>\n\nThis should do. I won't have time to sew on a little patch with '{name}' embroidered on it or anything, but anyone looking closely at you should be convinced that you're an overseer by the time we're done with you.", objectives = "Bring an Overseer's Uniform to Mountaineer Kilian at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12184] = { id = 12184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultivating an Image", description = "Now that we've got the uniform, we've got to get enough information to complete your camouflage.\n\nRaegar brought along this camera to document the team's finds, but I have a different use in mind. I want you to take it with you to Dun Argol and use it to capture the images of iron dwarves.\n\nOf course, your models aren't going to be a cooperative lot, so you may have to, err... subdue them first. Bring back the camera and the images when you're done.", progress = "Did you get those snapshots?", completion = "Good, these should do. Now, to create a kit to pass you off as a convincing iron dwarf.", objectives = "Use Kilian's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Mountaineer Kilian at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12185] = { id = 12185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put on Your Best Face for Loken", description = "Using the images you've captured, I've created everything you need for your overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself.\n\nTake the kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", completion = "Could it be that Loken isn't really exaggerating? The titans' stone and iron sons fighting against each other for control of the ancient city of Ulduar. This is madness, {name} and it could destroy our only chance to learn the true history of dwarvenkind!", objectives = "Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Mountaineer Kilian at Prospector's Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12186] = { id = 12186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Winner" }
quests[12187] = { id = 12187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Participant" }
quests[12188] = { id = 12188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken Blight and You: How Not to Die", description = "The details behind the functionality of the blight are hardly important. All you need to know is that it does the job it was designed to do. I have managed to synthesize a strain of the blight that is inert.\n\n<Middleton uncorks a vial and inhales.>\n\nSee, my body is still, mostly, intact. Now mix this with a reactive agent and we'd all be turned to shapeless piles of goo.\n\nOn the beach south of here you will find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic residue.", progress = "The residue will be used as the reactive agent to activate the blight!", completion = "This will do nicely, {name}. Did those pathetic whelps put up a fight or did they just shower you with ghostly tears of sorrow?\n\nAh, they get so emotional...", objectives = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to bring him 10 Ectoplasmic Residue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12189] = { id = 12189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imbeciles Abound!", description = "The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the \"victory puzzle.\"\n\n<Sintar sighs.>\n\nIt is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs!\n\nYou must travel to Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and let him know that I am waiting on the package.", completion = "We ran into a little - MINOR - problem. Everyone that tried handling the blight vaporized. We're working on adjusting the formula a tad so it doesn't instantly kill you for looking at it sideways. The good news is that I think I've almost got it!", objectives = "Travel to Venomspite in Dragonblight and speak with Chief Plaguebringer Middleton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12190] = { id = 12190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say Hello to My Little Friend", description = "Harkor's gunna drop a gold brick when he sees these choice ingredients. All that be left is gettin' them to him.\n\nHe's camped out on the eastern coast near dem haunted ruins - Drakil'jin, dey be called.\n\nYou'll likely be makin' it there before I can finish up with these corpses... unless, ya think you'd rather try your hand at embalming?", progress = "What can I do fer ya?", completion = "Well now! Good ol' Prigmon sent ya did he?\n\nThis should make fer some mighty fine eatin'. Needs just a couple things...", objectives = "Prigmon wants you to bring Harkor's Ingredients to Harkor at Harkor's Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12191] = { id = 12191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chug and Chuck!", description = "Hey, you look like you've got a good arm!\n\nWe like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss!\n\nThink you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", progress = "Chug from the mug, then chuck the mug at S.T.O.U.T. I think he can withstand the pounding. I wouldn't have stol.. er... built him if he couldn't!", completion = "Wow...  S.T.O.U.T. didn't break... Hmm... Who would have guessed?\n\nI mean, hey, you did it!  Your aim is true, or at least true enough to help guard the camp.  I think you're ready now to take on the Dark Irons if they show up again.", objectives = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12192] = { id = 12192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, {class}, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, {name}.  Enjoy the rest of Brewfest.", objectives = "Talk to Bizzle Quicklift in the Brewfest camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12193] = { id = 12193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12194] = { id = 12194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12195] = { id = 12195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unexpected 'Guest'", description = "A recent hunting expedition brought back more than just game.\n\nThey encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have information we can use to strike at our ancient enemy, but before he's of any use to us, we must bring down his fever.\n\nThe horns of the silvercoat stags, who roam the nearby forest, have long been used to make healing poultices. If you can bring enough of the horns to me, we'll see if the poultice can bring our 'guest' around.", progress = "Did you bring the horns?", completion = "These should serve. Now, let's see if it works.", objectives = "Bring 5 Mature Stag Horns to Tormak the Scarred at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12196] = { id = 12196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Ground Up", description = "We don't have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts.\n\nI think you should go back there and pick up enough of them for me to make a golem from this blueprint.\n\nThey're probably scattered around any of the buildings where the iron rune-smiths are working.\n\nPlease hurry, {name}. That Tormak looks like he's just waiting for an excuse to carry out his threat!", progress = "D-did you b-b-bring those golem parts?", completion = "<Rokar wipes his forehead with the back of his hand.>\n\nOh, thank the Light. He was threatening not to feed me until you returned. Let's sort through this pile of parts and see what we can make.", objectives = "Bring 8 War Golem Parts to Prospector Rokar at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12197] = { id = 12197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have the Power", description = "Well, we've got the shell of a golem, but that's not good enough for Tormak. He doesn't realize that these things don't just come together and miraculously start working! We're going to need power cells to animate it.\n\nWhen I was in Dun Argol, I noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the cells. We'll need one from each to power our golem.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", progress = "Do you have those power cells?", completion = "<Rokar takes the batteries from you.>\n\nThese are low, but they'll be enough to start up the golem. He's nowhere near ready for battle, though.", objectives = "Bring Durar's Power Cell and Kathorn's Power Cell to Prospector Rokar at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12198] = { id = 12198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Or Maybe We Don't", description = "The golem's cells have just enough power to run it at the lowest levels, but it can't power any of its combat systems.\n\nThe good news is that the perimeter of Dun Argol is patrolled by lightning sentries. We should be able to use their power to charge up the golem's weapon systems.\n\nBring the golem with you, take it close to them, it will absorb the power as the sentries die.", progress = "Did you get that golem charged? Tormak is getting impatient again...", completion = "Well, now Tormak can't complain anymore. This baby's as ready as I can make it.\n\nAfter you tear your way through Dun Argol with it, that overgrown cow'll have to release me.", objectives = "Charge your War Golem with the energy from 10 Lightning Sentries and return to Prospector Rokar at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12199] = { id = 12199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down the Iron Thane", description = "Now that the golem is fully charged, it can be used against the leader at Dun Argol.\n\nWhen I observed Iron Thane Furyhammer, he was always guarded by a personal golem that shielded him from all harm.\n\nThat construct, called The Anvil, can be disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. You'll be able to activate and take control of your golem inside Dun Argol.\n\nThe thane is in the main plant at the top and supervises production from the bottom level.", progress = "Please tell me it worked...", completion = "So the prospector made good on his promises? Good. I was beginning to wonder if all of this scrounging for bits of metal and stealing building materials would amount to anything.\n\nIt's a shame he's of no further use to us.", objectives = "Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Tormak the Scarred at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12200] = { id = 12200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Dragon Tears", description = "With an inert specimen of the blight compound complete and the activating agent in hand there only remains a need for a suitable shell to house the components.\n\nSouthwest of here, on the shores of central Dragonblight, is where you will find the Emerald Dragonshrine. Within the shrine you will find the hardened remnants of a green dragon's tear drop. I don't know the whole story, but apparently they cry a lot right before they die. Go figure.\n\nGo to the Emerald Dragonshrine and gather tears.", progress = "Fortunate it is that we have a location nearby holding a surplus of emerald dragon tears. I would have had to send you to Feralas otherwise.", completion = "I do believe that the blight is now ready for a field test. Fortuitously, the dread citadel, Naxxramas, is laying siege to Wintergarde Keep. From beneath the very earth that Wintergarde was built upon rise the living dead, eager to do the bidding of Kel'Thuzad.\n\nThe Alliance are, of course, outmanned and outgunned. The people laid to rest in the Wintergarde Mausoleum awaken, hungering for flesh!\n\nPerhaps we shall give them a taste of the blight, yes?", objectives = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to collect 8 Emerald Dragon Tears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12201] = { id = 12201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Overseer's Shadow", description = "It sounds like this Loken is the mastermind behind the sudden preparations for war on the part of the iron dwarves.\n\nOnly the highest ranking irons are likely to have access to him, so we'll have to make you into an overseer to find out what's going on in there.\n\nI have a plan, for that, but we'll need some supplies.\n\nFind one of the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his uniform.", progress = "Did you get the uniform?", completion = "This should work, but there's still the matter of the rest of your disguise. Even those dimwitted metal dwarves will recognize an impostor with a stolen suit.", objectives = "Bring an Overseer's Uniform to Scout Vor'takh at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12202] = { id = 12202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultivating an Image", description = "Now we have to finish the job of making you as repulsive as those iron dwarves.\n\nThe best way to do that is to base your disguise on the ugly mugs of real iron dwarves.\n\nWhen Tormak's hunting party discovered that wayward prospector, they took the camera he carried. Now, I suppose, we'll get the chance to use it.\n\nTake it with you to Dun Argol, kill some iron dwarves, and record their likenesses in this device. Bring it back once you have enough examples.", progress = "Did you get those snapshots?", completion = "These should serve. By Garrosh, these creatures are ugly.", objectives = "Use Rokar's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Scout Vor'takh at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12203] = { id = 12203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loken's Orders", description = "I've created everything else you'll need for your overseer disguise kit. Try not to retch when you put it on. I took pains to make it as true to reality as possible.\n\nTake the kit with you southeast to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", completion = "So he means to foment civil war between the factions of the titans' creation? Why does this titan city of Ulduar mean so much to him? I suppose this is what Kurun and his giants are hoping to prevent.\n\nWell, I doubt we're in a position to keep the giants from fighting each other, but we can find a way to use this to our advantage. I must inform our leaders at once.", objectives = "Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Scout Vor'takh at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12204] = { id = 12204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Name of Loken", description = "The iron dwarves stand as one of the fiercest and most coordinated foes in Northrend. Wherever we have traveled, they have battled us with the name of Loken on their lips.\n\nWe must learn who this Loken is and what he seeks. The locals may be of help.\n\nTo the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named Gavrock. Ask them about this Loken. They've got to know something of use.", completion = "So he is the mastermind behind the iron dwarves? We must find out what he has been ordering the iron dwarves of Dun Argol to do.", objectives = "Speak with Hugh Glass and Gavrock about Loken, then report your findings to Scout Vor'takh at Camp Oneqwah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12205] = { id = 12205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: The Scarlet Onslaught", description = "By order of High Executor Wroth all members of the illegal organization known as the Scarlet Onslaught are to be put to death immediately.\n\nNo quarter is to be offered, and those proceeding to action upon this decree should be aware that any who are captured by the humans will be left to die, or worse!\n\nIn the High Executor's words, \"Paint the snow red with their blood!\"", completion = "Very well done, {race}. I trust that you were cleverly vicious in your slaying?\n\nLet's see, how much I can offer you from the coffins... er, excuse me, coffers?", objectives = "Kill 20 members of the Scarlet Onslaught and report to High Executor Wroth at Venomspite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12206] = { id = 12206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blighted Last Rites", description = "Have you read the wanted poster? What is the high executor thinking?!\n\n<Vicky looks around and continues in hushed tones.>\n\nWe can't very well have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as the Scourge, now can we?\n\nNo, I'm in total agreement with you, we have to do something about the corpses.\n\nI have just the thing. Take this blight that we just created and test it on the prisoner in the cage right here.\n\nNo muss, no fuss, no returning enemies.", progress = "Did you do it?\n\nHey, I forgot to tell you that you probably shouldn't let any of that stuff get on you! It's nasty, and you'll never get the stains out, let alone have a hell of a time healing the bubbled-away fleshy bits.", completion = "WHAT?! That's impossible! We've perfected the blight. It has a one-hundred percent lethality.\n\n<The apothecary wrings her hands, concern crossing her unliving visage. Clearly frustrated, she continues in an angry tone.>\n\nThis is just really odd. Hand me that flask, {class}. I'm not going to be known as the apothecary that ruined everything!", objectives = "Apothecary Vicky Levine at Venomspite has asked you to test the Flask of Blight upon the Scarlet Onslaught Prisoner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12207] = { id = 12207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Fall", description = "Long ago, powerful druids planted a tree to the northeast of here.\n\nIt was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed.\n\nEver since we arrived here, the earth has spoken to me, {name}.  Its cries of pain come from the places where Vordrassil's remains fell on the ground.\n\nCorrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.", progress = "Have you obtained the samples, {name}?", completion = "This slime is foul with a darkness far more ancient than their worldly forms would indicate.  The land itself has a memory of this evil for as long as it has existed.\n\nWe must find out more, {name}.", objectives = "Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12208] = { id = 12208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Troll Hunting", description = "Good for nothing wretches!\n\nThey could have had it easy. We extended our hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have let them be.\n\nBut no, the prideful little ice trolls decided that they wanted it rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak anyway.\n\nWe've contracted a gang to deliver us captured trolls. Talk to Samir if you want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.", completion = "Here to get in on the bounty action, eh?", objectives = "Sergeant Thurkin told you to speak to Samir at Granite Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12209] = { id = 12209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materiel Plunder", description = "Ah good, new meat. Do you wish to prove yourself, new meat?\n\nThe Scarlet Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to the south. If we're going to fight them, we'll need more armor and weapons than I can make in such a short time.\n\nWhy don't we take theirs?\n\nMore to the point, why don't YOU take theirs?", progress = "I'll take what armor and weapons you can steal for me, new meat.\n\nThough they'll be of inferior quality to what I can make here, it's better than nothing.", completion = "You do not smell so fresh now, new meat.\n\nVery well, all of this will do. By what name might I call you, {class}?", objectives = "Quartermaster Bartlett at Venomspite has asked you to steal 8 Scarlet Onslaught Armor and 8 Scarlet Onslaught Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12210] = { id = 12210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Season!", description = "You, {race}! No sense standing around here when there's work to be done!\n\nDrak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to ensure safe passage for the Alliance. But until we get the numbers to make an assault, we'll have to content ourselves in thinning out the ice trolls and collecting intel.\n\nTo that end, we've conscripted a gang of thugs to capture and deliver live trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. He'll direct you further.", completion = "Here to get in on the bounty action, eh?", objectives = "Lieutenant Dumont at Amberpine Lodge wants you to speak to Samir at Granite Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12211] = { id = 12211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Not Rise!", description = "I don't understand it. The blight should have worked!\n\nNo sense worrying about it now.\n\n<The apothecary seems relieved for some reason.>\n\nThough it doesn't work on the Onslaught for some strange reason, we still need to keep their priests from raising them.\n\nI have another idea, one that their corpses shouldn't have any protection from.\n\n{name}, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!", completion = "Oh good! For a moment I thought I was going to have to test the rats out on someone to make sure that they weren't defective.\n\nProgress, finally!", objectives = "Apothecary Vicky Levine at Venomspite has asked you to use her Container of Rats to pick clean the corpses of 15 Scarlet Onslaught members at New Hearthglen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12212] = { id = 12212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenishing the Storehouse", description = "G'day, {class}.\n\nThe good lieutenant here says that there's been a Horde raid on our storehouse that's left our food supply dangerously low.\n\nNo doubt we'll make those cretins pay, but first we need to focus our attention on restocking. My men are doing all they can, but we're going to need every able body to contribute if we're to avert a crisis.\n\nYou should have no trouble harvesting venison from the local stag in these parts. Happy hunting!", progress = "How goes the hunt, {race}?", completion = "These are some choice pieces of meat!", objectives = "Master Woodsman Anderhol at Amberpine Lodge wants you to kill Tallhorn Stag and collect 8 Succulent Venison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12213] = { id = 12213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness Beneath", description = "Something... dark... happened to the tree Vordrassil.  After the druids decided to destroy it, its hollow remains grew roots deep into the ground.\n\nI want you to go to the three locations to the northeast where the tree's trunk shattered and go as far beneath the ground as you can.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  This might shed some light on what happened to Vordrassil and why it failed to become a world tree.", completion = "This orb... it has been tainted by... a purely evil force.\n\nWhatever else I might learn from studying this energy, one thing is certain.  I must destroy this orb as soon as possible.  Its corrupting force is just too strong.", objectives = "Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12214] = { id = 12214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Remounts", description = "Hello. I am Hansel. Pleased to meet you, <sir/ma'am>.\n\nThe high executor came to me and said, 'Hansel, I want you to get us new mounts.'\n\nWhere does he think dreadsteeds come from? The ground?\n\n<whispering> Actually, they do if you can find a horse graveyard.\n\nBut we don't have one of those, so what we need you to do is go south to New Hearthglen, kill the knights, take their riding crops, and steal their warhorses.\n\nRide the horse back to me here and hand over the reins, if you would.", progress = "I'm sure glad that you came around. I was afraid that I was going to have to go down there and rustle them up myself.", completion = "Ah, nothing makes me happier than a job well done.\n\nYou've done Venomspite a great service in acquiring these horses, {class}.", objectives = "Hansel Bauer at Venomspite has asked you to steal 3 Onslaught Warhorses and deliver them to him, handing over the reins when you do so.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12215] = { id = 12215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Them or Us!", description = "As if we didn't have enough to concern ourselves with....\n\nWith the present food crisis, we find ourselves competing for food with the local worgs. The situation is becoming more dire, and I fear that if we don't address the issue immediately we'll soon find ourselves with nothing to hunt.\n\nScour the forest, {race}. Kill any graymist you find. Recent reports have sighted a concentration of them on the other side of the river west of here.", completion = "Good work, {class}.\n\nThis should help ensure that the wildlife in these parts ends up where it should - roasting over our fires.", objectives = "Anderhol at Amberpine Lodge wants you to find and kill 6 Graymist Hunters in Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12216] = { id = 12216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Their Rear!", description = "We've all been working hard and it's beginning to pay off, but we're still far from our goal. We need much more meat than we have and it's growing clear that the local stag population won't be enough by itself.\n\nI'm afraid we need you to turn your attention to more dangerous prey - the grizzlies that give this region its name. They're plentiful, and they're well fed from the abundant fish that swim in these streams.\n\nBe safe, {class}!", progress = "The mighty {class} has returned!", completion = "Outstanding!\n\nOur stores are nearly replenished now. You've done your part, {name}.", objectives = "Anderhol at Amberpine Lodge wants you to collect 8 Grizzly Flanks from the Grizzly Bears in Grizzly Hills.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12217] = { id = 12217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle Eyes", description = "Well, {name}, we've determined how the Horde was able to locate our hidden stores of food.\n\nIt turns out that they were binding their sight to the unsuspecting eagles that soar above the trees here. Using eagle vision, they were able to effectively spy on our every action.\n\nBy order of the lieutenant, we've got to hunt down these majestic birds in order to thwart our enemy.", completion = "A somber task, I know. But we can rest easier now knowing the enemy's eyes are no longer upon us.", objectives = "Anderhol in Amberpine Lodge wants you to kill 5 Imperial Eagles and then report back to him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12218] = { id = 12218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Good Word", description = "Before I can ship you off to Doctor Malefious with the good news, you will have to run a simple field test of the blight with the modifications I have made.\n\nThe hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle from the east gate and drive it northeast through Vengeance Pass until you reach the twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead that cover the area. Report back to me with the results!", completion = "As much as it irritates me that we may have assisted the Alliance, I declare the field test a success! Next stop: Agmar's Hammer!", objectives = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to use the Forsaken Blight Spreader's Blight Bomb to destroy 30 Hungering Dead on the outskirts of the Carrion Fields.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12219] = { id = 12219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Failed World Tree", description = "My ancestors once planted a tree in the middle of the Grizzly Hills.\n\nIt was called Vordrassil and it was to become a world tree.\n\nFor reasons long forgotten, after the tree was fully grown, they decided it needed to be destroyed.  Its giant trunk splintered at three locations in the area to the north.\n\nWhere the tree touched the ground, foul ooze began to crawl the earth.  Bring me slime samples so I can begin my work and the earth can be healed.", progress = "Have you gathered the samples, {name}?", completion = "The slime is not natural, {name}.  Its very nature is corrupt and... evil.\n\nWe must find out more.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12220] = { id = 12220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Influence", description = "When the tree Vordrassil fell, its hollow remains grew roots deep into the ground.\n\nI want you to go north of here to the three locations where the trunk shattered and go as far beneath the ground as you can.  You'll find them west of Grizzlemaw.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  If we're to heal the land, we must first find out what caused Vordrassil to fail as a world tree all those years ago.", completion = "The energy in the orb is... overpowering...\n\nA dark force has tainted the ground near Vordrassil's remains.  We will need to investigate more.", objectives = "Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12221] = { id = 12221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken Blight", description = "I have prepared a package that must be delivered to Doctor Sintar Malefious at Agmar's Hammer. The contents of the package include the final blight specimen along with instructions on preparation and samples of the reactive agent.\n\nYou will find Agmar's Hammer in western Dragonblight. Just look for the black, jagged metal orc buildings - that will be Agmar's Hammer.", progress = "About bloody time!", completion = "<Doctor Malefious looks through the contents of the package.>\n\nGlorious! Exactly to specifications!\n\nHere is your payment, {name}. Keep what you've seen and done to yourself. This work is all classified - information is given out on a need to know basis.", objectives = "Deliver The Forsaken Blight to Doctor Sintar Malefious at Agmar's Hammer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12222] = { id = 12222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Flamebinders", description = "Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south.\n\nThe most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune.\n\nThe Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.", progress = "Did you collect those talismans?", completion = "With the talismans in hand, the drake will have no choice but to obey you. I can't wait to see the look on the thane's face when he realizes you've commandeered his proto-drake.", objectives = "Bring 3 Flame-Imbued Talismans to Woodsman Drake at Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12223] = { id = 12223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Ranks", description = "There's a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde's treachery, Amberpine will be vulnerable.\n\nTravel to Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft target.\n\nSlay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.", completion = "Well done, {name}. Now, we must follow through and press the advantage.", objectives = "Kill 12 Dragonflayer Huscarls and return to Woodsman Drake at Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12224] = { id = 12224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kor'kron Vanguard!", description = "You have done well, <brother/sister>. All that you have faced, you have done as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your foot! The taunka, brave and powerful new members of the Horde, because of you! Our super-weapon against the Scourge, tested and perfected by you!\n\nThe time has come, the moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.", completion = "Lok'tar ogar! I have heard much about you, {name}. Your battle scars run deep - a testament to your dedication and power!\n\nWith the flanking attacks of the Lich King crushed in both the west and east, only the forces at the gate remain. We gain ground each day, soon to break through this wall and into Icecrown!\n\nOnce we stop the skeletal dragons, Highlord Fordragon and I will take the field.", objectives = "Report to Saurfang the Younger at the Kor'kron Vanguard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[12225] = { id = 12225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmm... Amberseeds!", description = "Your stomach growls as the pungent smell of hearty nuts draws your attention to the bucket of seeds.\n\nSome thoughtful soul has obviously left these complimentary morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and devour them.\n\nThe seeds do not disappoint. Finding yourself hungry for more, you set out to discover their origins....", completion = "You did what!!!\n\nThose were Amberseeds! And that was an entire harvest's worth!\n\nThose magical seeds may have been the answer to our food crisis. Believe me when I tell you, {name}, you're going to make this right!", objectives = "Speak with Master Woodsman Anderhol in Amberpine Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
